    "proactive_status_stable": "\u092d\u0942\u091c\u0932 \u0938\u094d\u0925\u093f\u0924\u093f \u0938\u094d\u0925\u093f\u0930",
    "proactive_what_changed": "\u0915\u094d\u092f\u093e \u092c\u0926\u0932\u093e\u0935 \u0939\u0941\u0906",
    "proactive_what_to_do": "\u0905\u0928\u0941\u0936\u0902\u0938\u093f\u0924 \u0915\u093e\u0930\u094d\u0930\u0935\u093e\u0908",
    "provenance_water_watch": "\u091c\u0932\u0915\u0943\u0937\u093f \u0938\u0902\u0926\u0930\u094d\u092d \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u0921\u0947\u091f\u093e\u0938\u0947\u091f \u2022 DWLR, \u0930\u093f\u092e\u094b\u091f \u0938\u0947\u0902\u0938\u093f\u0902\u0917 \u0914\u0930 \u092a\u0942\u0930\u094d\u0935\u093e\u0928\u0941\u092e\u093e\u0928\u094b\u0902 \u0938\u0947 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u093f\u0924",
    "ask_water_watch_voice": "\u0915\u093f\u0938\u093e\u0928 AI \u0938\u0947 \u092a\u0942\u091b\u0947\u0902",
    "proactive_engine_title": "\u0938\u0915\u094d\u0930\u093f\u092f \u092d\u0942\u091c\u0932 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e \u090f\u0935\u0902 \u092a\u0942\u0930\u094d\u0935 \u091a\u0947\u0924\u093e\u0935\u0928\u0940 \u092a\u094d\u0930\u0923\u093e\u0932\u0940",
    "proactive_engine_desc": "DWLR \u092a\u094d\u0930\u0935\u0943\u0924\u094d\u0924\u093f\u092f\u094b\u0902, 30-90 \u0926\u093f\u0935\u0938\u0940\u092f \u092a\u0942\u0930\u094d\u0935\u093e\u0928\u0941\u092e\u093e\u0928\u094b\u0902, \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0935\u093f\u0938\u0902\u0917\u0924\u093f\u092f\u094b\u0902 \u0914\u0930 \u0909\u092a\u0917\u094d\u0930\u0939 \u0925\u0930\u094d\u092e\u0932 \u0921\u0947\u091f\u093e \u0915\u093e \u092c\u0939\u0941-\u0938\u0902\u0915\u0947\u0924 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923\u0964",
    "refresh_intelligence": "\u0928\u0947\u091f\u0935\u0930\u094d\u0915 \u0924\u093e\u091c\u093c\u093e \u0915\u0930\u0947\u0902",
    "proactive_provenance_disclaimer": "\u0938\u0902\u0926\u0930\u094d\u092d \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u092e\u094b\u0921: CGWB DWLR \u0938\u0902\u0926\u0930\u094d\u092d \u0928\u0947\u091f\u0935\u0930\u094d\u0915 \u0914\u0930 \u0909\u092a\u0917\u094d\u0930\u0939 \u0938\u0902\u0915\u0947\u0924\u094b\u0902 \u092a\u0930 \u0906\u0927\u093e\u0930\u093f\u0924\u0964",
    "kpi_monitored_stations": "\u0928\u093f\u0917\u0930\u093e\u0928\u0940 \u0915\u0941\u090f\u0902",
    "kpi_critical_risks": "\u0917\u0902\u092d\u0940\u0930 \u091a\u0947\u0924\u093e\u0935\u0928\u093f\u092f\u093e\u0902",
