    "no_proactive_alerts_desc": "\u091a\u092f\u0928\u093f\u0924 \u092e\u093e\u0928\u0926\u0902\u0921\u094b\u0902 \u0915\u0947 \u0938\u092d\u0940 \u0928\u093f\u0917\u0930\u093e\u0928\u0940 \u0938\u094d\u091f\u0947\u0936\u0928 \u0935\u0930\u094d\u0924\u092e\u093e\u0928 \u092e\u0947\u0902 \u0938\u094d\u0925\u093f\u0930 \u0938\u094d\u0925\u093f\u0924\u093f \u092e\u0947\u0902 \u0939\u0948\u0902\u0964",
