    "Detect unusual groundwater changes, distinguish possible water-level stress from sensor-quality issues, and identify areas that may need attention.": "असामान्य भूजल परिवर्तनों का पता लगाएं, जल-स्तर के तनाव और सेंसर-गुणवत्ता की समस्याओं में अंतर समझें, और ध्यान देने योग्य क्षेत्रों की पहचान करें।",
    "An unusual groundwater change can indicate increasing water stress, abnormal extraction, or a data-quality issue. Early review can help farmers and officials respond before water availability becomes a larger problem.": "असामान्य भूजल परिवर्तन बढ़ते जल तनाव, अत्यधिक दोहन या डेटा-गुणवत्ता संबंधी समस्या का संकेत हो सकता है। समय पर समीक्षा से किसानों और अधिकारियों को जल उपलब्धता की समस्या गंभीर होने से पहले कदम उठाने में मदद मिलती है।",
