    "Plain-language guide to groundwater early warning flags and data quality signals": "भूजल पूर्व चेतावनी और डेटा गुणवत्ता संकेतों की सरल मार्गदर्शिका",
    "Water level falling faster than expected": "जलस्तर अपेक्षा से अधिक तेजी से गिर रहा है",
    "Groundwater level is falling faster than the expected local pattern. This may indicate concentrated pumping or rapid localized depletion.": "भूजल स्तर स्थानीय अपेक्षित स्तर की तुलना में तेजी से गिर रहा है। यह अत्यधिक पंपिंग या तेजी से स्थानीय कमी का संकेत हो सकता है।",
    "Repeated drawdown without normal recovery": "सामान्य बहाली के बिना लगातार गिरावट",
    "Repeated drawdown may indicate unusually high or sustained water withdrawal without the usual recharge window.": "लगातार गिरावट पुनर्भरण के बिना असामान्य रूप से उच्च या निरंतर जल दोहन का संकेत हो सकती है।",
    "Expected readings not received": "अपेक्षित रीडिंग प्राप्त नहीं हुई",
    "Expected observations are missing or arriving later than expected. Commonly caused by temporary network interruptions or power cycling.": "अपेक्षित अवलोकन अनुपलब्ध हैं या देरी से आ रहे हैं। यह आमतौर पर अस्थायी नेटवर्क रुकावट या पावर रीसेट के कारण होता है।",
    "Unusual reading patterns requiring check": "असामान्य रीडिंग पैटर्न, जांच आवश्यक",
    "Readings show patterns that may require sensor or telemetry verification before drawing firm hydrogeological conclusions.": "रीडिंग ऐसे पैटर्न दिखाती हैं जिनमें ठोस भूजल निष्कर्ष निकालने से पहले सेंसर या टेलीमेट्री सत्यापन आवश्यक हो सकता है।",
    "Rapid water level increase": "जलस्तर में तेजी से वृद्धि",
    "Groundwater level has increased sharply, potentially following heavy localized rainfall, canal release, or surface recharge.": "भूजल स्तर में तेजी से वृद्धि हुई है, जो भारी स्थानीय वर्षा, नहर के पानी या भूतल पुनर्भरण के कारण हो सकती है।",
    "Recommended Next Steps": "अनुशंसित अगले कदम",
    "Actionable guidance for farmers and field officials when unusual signals are detected": "असामान्य संकेत मिलने पर किसानों और क्षेत्रीय अधिकारियों के लिए व्यावहारिक मार्गदर्शन",
    "Water Drop": "जलस्तर गिरावट",
