    "Inspect Neighboring Stations": "निकटवर्ती स्टेशनों का निरीक्षण करें",
    "Explore nearby monitoring stations on the map to determine whether the drop is localized or spread across the block.": "नक्शे पर आस-पास के निगरानी स्टेशनों को देखें ताकि पता चल सके कि गिरावट स्थानीय है या पूरे ब्लॉक में फैली है।",
