    "Active in Middle Gangetic Basin (UP, Bihar, West Bengal) and Narmada Valley (MP). Shallow aquifers exhibit +0.3m to +0.5m post-monsoon water table recovery.": "मध्य गंगा बेसिन (यूपी, बिहार, पश्चिम बंगाल) और नर्मदा घाटी (एमपी) में सक्रिय। उथले जलभृत मानसून के बाद +0.3 मीटर से +0.5 मीटर जलस्तर सुधार प्रदर्शित करते हैं।",
    "Adopt mixed cropping (Maize + Pulses) to balance root-zone moisture draw.": "जड़ क्षेत्र की नमी को संतुलित करने के लिए मिश्रित फसल प्रणाली (मक्का + दालें) अपनाएं।",
    "All values displayed are simulated DWLR data intended for model evaluation and operational planning. Future phases will integrate live CGWB REST telemetry endpoints and IMD meteorological grids.": "प्रदर्शित सभी मान मॉडल मूल्यांकन और परिचालन योजना के लिए सिम्युलेटेड डीडब्ल्यूएलआर डेटा हैं। भविष्य के चरणों में लाइव सीजीडब्ल्यूबी रेस्ट टेलीमेट्री एंडपॉइंट्स और आईएमडी मौसम ग्रिड एकीकृत किए जाएंगे।",
    "Aquifer Rebound": "जलभृत सुधार",
    "Aquifers Depleting < 30 Days": "30 दिनों से कम में समाप्त हो रहे जलभृत",
    "Calculates 30-day moving average depletion slope (m/month) based on telemetry hydrostatic head pressure records.": "टेलीमेट्री हाइड्रोस्टेटिक हेड प्रेशर रिकॉर्ड के आधार पर 30-दिवसीय मूविंग एवरेज गिरावट दर (मीटर/माह) की गणना करता है।",
    "Clear silt from percolation tanks and farm recharge shafts.": "रिसाव तालाबों और खेत के पुनर्भरण शाफ्ट से गाद साफ करें।",
    "Comparative state-level forecast trajectory, rainfall expectation, and agronomic priority actions": "तुलनात्मक राज्य-स्तरीय पूर्वानुमान प्रक्षेपवक्र, वर्षा की संभावना और कृषि संबंधी प्राथमिकता कार्रवाइयां",
    "Concentrated in North-Western alluvial plains (Punjab, Haryana, Rajasthan) and hard-rock peninsular pockets (Kolar, Anantapur). Requires immediate crop substitution and night pumping schedules.": "उत्तर-पश्चिमी जलोढ़ मैदानों (पंजाब, हरियाणा, राजस्थान) और प्रायद्वीपीय कठोर चट्टानी क्षेत्रों (कोलार, अनंतपुर) में केंद्रित। तत्काल फसल परिवर्तन और रात्रि पंपिंग कार्यक्रम की आवश्यकता है।",
