    "Days-to-critical estimates are calculated from current hydrostatic drawdown slope and historical monsoon infiltration response. Projections adapt dynamically as seasonal rainfall and pumping patterns change.": "गंभीर सीमा तक के दिनों का अनुमान वर्तमान जलस्तर गिरावट दर और ऐतिहासिक मानसून पुनर्भरण प्रतिक्रिया से लगाया जाता है। मौसमी वर्षा और पंपिंग पैटर्न बदलने पर अनुमान गतिशील रूप से अनुकूलित होते हैं।",
    "Estimated as (Current Depth - Critical Threshold) / Daily Depletion Rate, bounded by seasonal rainfall recharge coefficients.": "(वर्तमान गहराई - गंभीर सीमा) / दैनिक गिरावट दर के रूप में अनुमानित, जो मौसमी वर्षा पुनर्भरण गुणांक द्वारा सीमित है।",
