    "Stay alert for sudden pumping anomalies during peak flowering.": "फूल आने के चरम समय में अत्यधिक पंपिंग की असामान्यताओं के प्रति सचेत रहें।",
    "Strict deficit irrigation. Run tube-wells only at night to reduce evaporation loss.": "कड़ी नियंत्रित सिंचाई अपनाएं। वाष्पीकरण से होने वाले नुकसान को कम करने के लिए केवल रात में ट्यूबवेल चलाएं।",
