    "Critical (Immediate Attention)": "গুরুতর (অবিলম্বে মনোযোগ)",
    "High (Review Soon)": "উচ্চ (শীঘ্রই পর্যালোচনা)",
    "Moderate (Monitor)": "মাঝারি (পর্যবেক্ষণ)",
    "Data Quality / Low (Verify)": "তথ্য গুণমান / নিম্ন (যাচাই করুন)",
    "Why Flagged / Insight:": "সতর্কতার কারণ / অন্তর্দৃষ্টি:",
    "Plain-Language Assessment": "সহজ ভাষায় মূল্যায়ন",
    "Recommended Follow-up Action": "প্রস্তাবিত পদক্ষেপ",
    "Technical Evidence & Telemetry Details": "প্রযুক্তিগত প্রমাণ ও টেলিমেট্রি বিবরণ",
    "Observation Timeline vs Expected Baseline": "পর্যবেক্ষণ সময়রেখা বনাম প্রত্যাশিত বেসলাইন",
    "Sensor / Hardware Status:": "সেন্সর / হার্ডওয়্যার স্থিতি:",
    "Observation Status": "পর্যবেক্ষণ স্থিতি",
    "Early Warning Signal": "প্রাথমিক সতর্কবার্তা সংকেত",
    "Understanding Groundwater Anomalies": "ভূগর্ভস্থ জলের অসঙ্গতি বুঝুন",
    "Plain-language guide to groundwater early warning flags and data quality signals": "ভূগর্ভস্থ জল প্রাথমিক সতর্কতা ও তথ্য গুণমান সংকেতের সহজ নির্দেশিকা",
    "Water level falling faster than expected": "জলের স্তর প্রত্যাশার চেয়ে দ্রুত হ্রাস পাচ্ছে",
    "Groundwater level is falling faster than the expected local pattern. This may indicate concentrated pumping or rapid localized depletion.": "ভূগর্ভস্থ জলের স্তর প্রত্যাশিত হারের চেয়ে দ্রুত হ্রাস পাচ্ছে। এটি অতিরিক্ত পাম্পিং বা দ্রুত স্থানীয় হ্রাসের ইঙ্গিত হতে পারে।",
    "Repeated drawdown without normal recovery": "স্বাভাবিক পুনরুদ্ধার ছাড়াই ক্রমাগত পতন",
    "Repeated drawdown may indicate unusually high or sustained water withdrawal without the usual recharge window.": "পুনর্ভরণ ছাড়াই ক্রমাগত পতন অতিরিক্ত বা অবিচ্ছিন্ন জল নিষ্কাশনের ইঙ্গিত হতে পারে।",
    "Expected readings not received": "প্রত্যাশিত রিডিং পাওয়া যায়নি",
    "Expected observations are missing or arriving later than expected. Commonly caused by temporary network interruptions or power cycling.": "প্রত্যাশিত পর্যবেক্ষণ অনুপস্থিত বা দেরিতে আসছে। এটি সাধারণত অস্থায়ী নেটওয়ার্ক সমস্যা বা পাওয়ার সমস্যার কারণে ঘটে।",
    "Unusual reading patterns requiring check": "অস্বাভাবিক রিডিং প্যাটার্ন, যাচাই প্রয়োজন",
    "Readings show patterns that may require sensor or telemetry verification before drawing firm hydrogeological conclusions.": "চূড়ান্ত সিদ্ধান্তে পৌঁছানোর আগে পাঠ্যগুলির সেন্সর বা টেলিমেট্রি যাচাইকরণ প্রয়োজন হতে পারে।",
    "Rapid water level increase": "জলের স্তরে দ্রুত বৃদ্ধি",
    "Groundwater level has increased sharply, potentially following heavy localized rainfall, canal release, or surface recharge.": "স্থানীয় ভারী বৃষ্টিপাত, খালের জল বা রিচার্জের কারণে ভূগর্ভস্থ জলের স্তর দ্রুত বৃদ্ধি পেয়েছে।",
    "Recommended Next Steps": "প্রস্তাবিত পরবর্তী পদক্ষেপ",
    "Actionable guidance for farmers and field officials when unusual signals are detected": "অস্বাভাবিক সংকেত পাওয়া গেলে কৃষক ও মাঠ কর্মকর্তাদের জন্য কার্যকরী নির্দেশিকা",
    "Water Drop": "জলস্তর পতন",
    "Check Groundwater Forecast": "ভূগর্ভস্থ জলের পূর্বাভাস দেখুন",
    "Review projected days-to-critical and consider adjusting pumping intervals or pump depth.": "সংকটপূর্ণ দিনগুলির পূর্বাভাস পর্যালোচনা করুন এবং পাম্পিং ব্যবধান সামঞ্জস্য করার কথা বিবেচনা করুন।",
    "Inspect Neighboring Stations": "নিকটবর্তী স্টেশনগুলি পরিদর্শন করুন",
    "Explore nearby monitoring stations on the map to determine whether the drop is localized or spread across the block.": "পতনটি স্থানীয় নাকি সমগ্র ব্লকে বিস্তৃত তা নির্ধারণ করতে মানচিত্রে নিকটবর্তী স্টেশনগুলি দেখুন।",
    "Data Quality": "তথ্য গুণমান",
    "Verify Latest Observations": "সাম্প্রতিক পর্যবেক্ষণ যাচাই করুন",
    "Check station telemetry status and wait for verification before planning critical irrigation changes.": "সেচ ব্যবস্থায় বড় পরিবর্তনের পরিকল্পনা করার আগে স্টেশনের স্থিতি পরীক্ষা করুন।",
    "Check Station Status": "স্টেশনের স্থিতি পরীক্ষা করুন",
    "Recharge Surge": "রিচার্জ বৃদ্ধি",
    "Optimize Crop Planning": "ফসল পরিকল্পনা অপ্টিমাইজ করুন",
    "Assess soil moisture and explore suitable crop rotation options to take advantage of improved water availability.": "মাটির আর্দ্রতা মূল্যায়ন করুন এবং উন্নত জলের প্রাপ্যতার সদ্ব্যবহার করতে উপযুক্ত ফসলের বিকল্প দেখুন।",
    "Where are Signals Concentrated? (Regional Breakdown)": "সংকেতগুলি কোথায় কেন্দ্রীভূত? (আঞ্চলিক বিবরণ)",
    "Ranked states by detected signals and primary anomaly category": "সনাক্তকৃত সংকেত ও প্রাথমিক অসঙ্গতি বিভাগ অনুসারে রাজ্যগুলির তালিকা",
