    "Active in Middle Gangetic Basin (UP, Bihar, West Bengal) and Narmada Valley (MP). Shallow aquifers exhibit +0.3m to +0.5m post-monsoon water table recovery.": "মধ্য গাঙ্গেয় অববাহিকা (ইউপি, বিহার, পশ্চিমবঙ্গ) এবং নর্মদা উপত্যকায় (এমপি) সক্রিয়। অগভীর জলজ স্তর বর্ষার পরে +০.৩মি থেকে +০.৫মি জলস্তর পুনরুদ্ধার প্রদর্শন করে।",
    "Adopt mixed cropping (Maize + Pulses) to balance root-zone moisture draw.": "মূল অঞ্চলের আর্দ্রতার ভারসাম্য বজায় রাখতে মিশ্র ফসল চাষ (ভুট্টা + ডাল) গ্রহণ করুন।",
    "All values displayed are simulated DWLR data intended for model evaluation and operational planning. Future phases will integrate live CGWB REST telemetry endpoints and IMD meteorological grids.": "প্রদর্শিত সমস্ত মান মডেল মূল্যায়ন এবং অপারেশনাল পরিকল্পনার জন্য সিমুলেটেড DWLR ডেটা। ভবিষ্যতের পর্যায়গুলিতে লাইভ CGWB REST টেলিমেট্রি এন্ডপয়েন্ট এবং IMD আবহাওয়া গ্রিড একত্রিত করা হবে।",
    "Aquifer Rebound": "অ্যাকুইফার পুনরুদ্ধার",
    "Aquifers Depleting < 30 Days": "৩০ দিনেরও কম সময়ে শেষ হতে চলা জলজ স্তর",
    "Calculates 30-day moving average depletion slope (m/month) based on telemetry hydrostatic head pressure records.": "টেলিমেট্রি হাইড্রোস্ট্যাটিক হেড প্রেসার রেকর্ডের ভিত্তিতে ৩০ দিনের চলমান গড় হ্রাসের ঢাল (মি/মাস) গণনা করে।",
    "Clear silt from percolation tanks and farm recharge shafts.": "পারকোলেশন ট্যাঙ্ক এবং খামারের রিচার্জ শ্যাফ্ট থেকে পলি পরিষ্কার করুন।",
    "Comparative state-level forecast trajectory, rainfall expectation, and agronomic priority actions": "তুলনামূলক রাজ্য-স্তরের পূর্বাভাসের গতিপথ, বৃষ্টিপাতের প্রত্যাশা এবং কৃষিভিত্তিক অগ্রাধিকার পদক্ষেপ",
    "Concentrated in North-Western alluvial plains (Punjab, Haryana, Rajasthan) and hard-rock peninsular pockets (Kolar, Anantapur). Requires immediate crop substitution and night pumping schedules.": "উত্তর-পশ্চিমের পলি সমভূমি (পাঞ্জাব, হরিয়ানা, রাজস্থান) এবং উপদ্বীপের শক্ত পাথুরে অঞ্চলে (কোলার, অনন্তপুর) কেন্দ্রীভূত। অবিলম্বে ফসল প্রতিস্থাপন এবং রাতে পাম্পিং সময়সূচী প্রয়োজন।",
