    "Days to critical distribution": "সংকটজনক সীমায় পৌঁছানোর দিনের বণ্টন",
    "Days-to-critical estimates are calculated from current hydrostatic drawdown slope and historical monsoon infiltration response. Projections adapt dynamically as seasonal rainfall and pumping patterns change.": "সংকটজনক দিনের অনুমান বর্তমান জলস্তর হ্রাসের ঢাল এবং ঐতিহাসিক বর্ষার রিচার্জ প্রতিক্রিয়া থেকে গণনা করা হয়। বৃষ্টিপাত এবং পাম্পিং প্যাটার্ন পরিবর্তনের সাথে সাথে পূর্বাভাস পরিবর্তিত হয়।",
    "Estimated as (Current Depth - Critical Threshold) / Daily Depletion Rate, bounded by seasonal rainfall recharge coefficients.": "(বর্তমান গভীরতা - সংকটজনক সীমা) / দৈনিক হ্রাসের হার হিসাবে আনুমানিক, যা ঋতুভিত্তিক বৃষ্টিপাত রিচার্জ সহগ দ্বারা আবদ্ধ।",
