    "Plain-language guide to groundwater early warning flags and data quality signals": "భూగర్భ జలాల ముందస్తు హెచ్చరికలు మరియు డేటా నాణ్యత సంకేతాల సరళమైన గైడ్",
    "Water level falling faster than expected": "నీటి స్థాయి ఊహించిన దానికంటే వేగంగా పడిపోతోంది",
    "Groundwater level is falling faster than the expected local pattern. This may indicate concentrated pumping or rapid localized depletion.": "భూగర్భ జలాల స్థాయి స్థానిక సాధారణ పరిమితి కంటే వేగంగా పడిపోతోంది. ఇది అధిక పంపింగ్ లేదా వేగవంతమైన స్థానిక తగ్గుదలను సూచించవచ్చు.",
