    "Repeated drawdown may indicate unusually high or sustained water withdrawal without the usual recharge window.": "రీఛార్జ్ విండో లేకుండా నిరంతర తగ్గుదల అసాధారణంగా ఎక్కువ లేదా స్థిరమైన నీటి వినియోగాన్ని సూచించవచ్చు.",
    "Expected readings not received": "ఆశించిన రీడింగ్‌లు అందలేదు",
    "Expected observations are missing or arriving later than expected. Commonly caused by temporary network interruptions or power cycling.": "ఆశించిన పరిశీలనలు అందడం లేదు లేదా ఆలస్యమవుతున్నాయి. ఇది సాధారణంగా తాత్కాలిక నెట్‌వర్క్ అంతరాయాలు లేదా విద్యుత్ సమస్యల వల్ల జరుగుతుంది.",
    "Unusual reading patterns requiring check": "అసాధారణ రీడింగ్ నమూనాలు, తనిఖీ అవసరం",
