    "Rapid water level increase": "నీటి స్థాయిలో వేగవంతమైన పెరుగుదల",
    "Groundwater level has increased sharply, potentially following heavy localized rainfall, canal release, or surface recharge.": "భారీ వర్షపాతం, కాలువ విడుదల లేదా ఉపరితల రీఛార్జ్ కారణంగా భూగర్భ జలాల స్థాయి బాగా పెరిగింది.",
    "Recommended Next Steps": "సిఫార్సు చేయబడిన తదుపరి చర్యలు",
