    "Active Deficit": "క్రియాశీల లోటు",
    "Active in Middle Gangetic Basin (UP, Bihar, West Bengal) and Narmada Valley (MP). Shallow aquifers exhibit +0.3m to +0.5m post-monsoon water table recovery.": "మధ్య గంగా బేసిన్ (యుపి, బీహార్, పశ్చిమ బెంగాల్) మరియు నర్మదా లోయ (ఎంపి) లో క్రియాశీలంగా ఉంది. రుతుపవనాల తర్వాత నిస్సార జలాశయాలు +0.3 మీ నుండి +0.5 మీ నీటిమట్టం పెరుగుదలను చూపుతాయి.",
    "Adopt mixed cropping (Maize + Pulses) to balance root-zone moisture draw.": "వేరు మండలంలో తేమను సమతుల్యం చేయడానికి మిశ్రమ పంటల పద్ధతిని (మొక్కజొన్న + పప్పుధాన్యాలు) అనుసరించండి.",
    "All values displayed are simulated DWLR data intended for model evaluation and operational planning. Future phases will integrate live CGWB REST telemetry endpoints and IMD meteorological grids.": "ప్రదర్శించబడిన అన్ని విలువలు మోడల్ మూల్యాంకనం మరియు కార్యాచరణ ప్రణాళిక కోసం అనుకరణ చేయబడిన DWLR డేటా. భవిష్యత్ దశల్లో లైవ్ CGWB REST టెలిమెట్రీ మరియు IMD వాతావరణ గ్రిడ్లు అనుసంధానించబడతాయి.",
    "Aquifer Rebound": "జలాశయం పెరుగుదల",
    "Aquifers Depleting < 30 Days": "30 రోజుల కంటే తక్కువలో తరిగిపోతున్న జలాశయాలు",
    "Calculates 30-day moving average depletion slope (m/month) based on telemetry hydrostatic head pressure records.": "టెలిమెట్రీ హైడ్రోస్టాటిక్ హెడ్ ప్రెజర్ రికార్డుల ఆధారంగా 30 రోజుల సగటు క్షీణత వాలును (మీ/నెల) లెక్కిస్తుంది.",
    "Clear silt from percolation tanks and farm recharge shafts.": "పర్కోలేషన్ ట్యాంకులు మరియు రీఛార్జ్ షాఫ్ట్‌ల నుండి పూడికను తొలగించండి.",
    "Comparative state-level forecast trajectory, rainfall expectation, and agronomic priority actions": "తులనాత్మక రాష్ట్ర స్థాయి సూచన పథం, వర్షపాతం నిరీక్షణ మరియు ప్రాధాన్య వ్యవసాయ చర్యలు",
    "Concentrated in North-Western alluvial plains (Punjab, Haryana, Rajasthan) and hard-rock peninsular pockets (Kolar, Anantapur). Requires immediate crop substitution and night pumping schedules.": "వాయవ్య మైదానాలు (పంజాబ్, హర్యానా, రాజస్థాన్) మరియు ద్వీపకల్ప ప్రాంతాల్లో (కోలార్, అనంతపురం) కేంద్రీకృతమై ఉంది. తక్షణ పంట మార్పిడి మరియు రాత్రి పంపింగ్ షెడ్యూల్ అవసరం.",
