    "Observation Timeline vs Expected Baseline": "निरीक्षण कालमर्यादा विरुद्ध अपेक्षित बेसलाइन",
    "Sensor / Hardware Status:": "सेन्सर / हार्डवेअर स्थिती:",
    "Observation Status": "निरीक्षण स्थिती",
    "Early Warning Signal": "पूर्वसूचना संकेत",
    "Understanding Groundwater Anomalies": "भूजल विसंगती समजून घ्या",
    "Plain-language guide to groundwater early warning flags and data quality signals": "भूजल पूर्वसूचना आणि डेटा गुणवत्ता संकेतांचे सोपे मार्गदर्शन",
    "Water level falling faster than expected": "पाण्याची पातळी अपेक्षेपेक्षा वेगाने घसरत आहे",
    "Groundwater level is falling faster than the expected local pattern. This may indicate concentrated pumping or rapid localized depletion.": "भूजल पातळी स्थानिक अपेक्षेपेक्षा वेगाने घसरत आहे. हे केंद्रित उपसा किंवा वेगाने होणाऱ्या स्थानिक घसरणीचे संकेत असू शकतात.",
    "Repeated drawdown without normal recovery": "सामान्य पुनर्प्राप्तीशिवाय सतत घसरण",
    "Repeated drawdown may indicate unusually high or sustained water withdrawal without the usual recharge window.": "पुनर्भरणाशिवाय वारंवार होणारी घसरण असामान्यपणे जास्त किंवा सतत पाण्याचा उपसा दर्शवू शकते.",
    "Expected readings not received": "अपेक्षित रीडिंग प्राप्त झाले नाही",
    "Expected observations are missing or arriving later than expected. Commonly caused by temporary network interruptions or power cycling.": "अपेक्षित निरीक्षणे गहाळ आहेत किंवा उशिरा येत आहेत. हे सामान्यतः तात्पुरत्या नेटवर्क अडथळ्यांमुळे किंवा पॉवर समस्येमुळे होते.",
    "Unusual reading patterns requiring check": "असामान्य रीडिंग नमुने, तपासणी आवश्यक",
    "Readings show patterns that may require sensor or telemetry verification before drawing firm hydrogeological conclusions.": "अंतिम निष्कर्षांवर येण्यापूर्वी सेन्सर किंवा टेलिमेट्री पडताळणीची आवश्यकता असू शकते.",
    "Rapid water level increase": "पाण्याच्या पातळीत झपाट्याने वाढ",
    "Groundwater level has increased sharply, potentially following heavy localized rainfall, canal release, or surface recharge.": "मुसळधार पाऊस, कालव्याचे पाणी किंवा पृष्ठभागावरील पुनर्भरणामुळे भूजल पातळीत झपाट्याने वाढ झाली आहे.",
    "Recommended Next Steps": "शिफारस केलेली पुढील पावले",
    "Actionable guidance for farmers and field officials when unusual signals are detected": "असामान्य संकेत आढळल्यास शेतकरी आणि क्षेत्रीय अधिकाऱ्यांसाठी मार्गदर्शक सूचना",
    "Water Drop": "पाणी घसरण",
    "Check Groundwater Forecast": "भूजल अंदाज तपासा",
    "Review projected days-to-critical and consider adjusting pumping intervals or pump depth.": "अपेक्षित गंभीर दिवसांचा आढावा घ्या आणि उपसा वेळ किंवा पंप खोली समायोजित करण्याचा विचार करा.",
    "Inspect Neighboring Stations": "शेजारील केंद्रांची पाहणी करा",
    "Explore nearby monitoring stations on the map to determine whether the drop is localized or spread across the block.": "घसरण स्थानिक आहे की संपूर्ण ब्लॉकमध्ये पसरली आहे हे पाहण्यासाठी नकाशावर जवळील केंद्रे तपासा.",
    "Data Quality": "डेटा गुणवत्ता",
