    "Check station telemetry status and wait for verification before planning critical irrigation changes.": "सिंचनात महत्त्वपूर्ण बदल करण्यापूर्वी केंद्राची स्थिती तपासा आणि पडताळणीची वाट पहा.",
    "Check Station Status": "केंद्राची स्थिती तपासा",
