    "Adopt mixed cropping (Maize + Pulses) to balance root-zone moisture draw.": "मुळांच्या भागातील ओलावा संतुलित करण्यासाठी मिश्र पिके (मका + डाळी) पद्धत स्वीकारा.",
    "All values displayed are simulated DWLR data intended for model evaluation and operational planning. Future phases will integrate live CGWB REST telemetry endpoints and IMD meteorological grids.": "प्रदर्शित केलेली सर्व मूल्ये मॉडेल मूल्यांकन आणि नियोजनासाठी सिम्युलेटेड DWLR डेटा आहेत. भविष्यातील टप्प्यात थेट CGWB REST टेलीमेट्री आणि IMD हवामान ग्रिड एकत्रित केले जातील.",
