    "Calculates 30-day moving average depletion slope (m/month) based on telemetry hydrostatic head pressure records.": "टेलिमेट्री हायड्रोस्टॅटिक हेड प्रेशर नोंदींच्या आधारे ३० दिवसांच्या सरासरी घसरण दराची (मी/महिना) गणना करते.",
