    "Groundwater Anomaly Detection & Early Warnings": "நிலத்தடி நீர் ஒழுங்கின்மை கண்டறிதல் மற்றும் முன் எச்சரிக்கைகள்",
    "Detect unusual groundwater changes, distinguish possible water-level stress from sensor-quality issues, and identify areas that may need attention.": "அசாதாரண நிலத்தடி நீர் மாற்றங்களைக் கண்டறிந்து, நீர் அழுத்தத்தையும் சென்சார் தரச் சிக்கல்களையும் வேறுபடுத்தி, கவனம் தேவைப்படும் பகுதிகளை அடையாளம் காணவும்.",
    "An unusual groundwater change can indicate increasing water stress, abnormal extraction, or a data-quality issue. Early review can help farmers and officials respond before water availability becomes a larger problem.": "அசாதாரண நிலத்தடி நீர் மாற்றம் அதிகரித்துவரும் நீர் அழுத்தம், அதிகப்படியான எடுப்பு அல்லது தரவு தரச் சிக்கலைக் குறிக்கலாம். முன்கூட்டியே மதிப்பாய்வு செய்வது நிலைமை மோசமடைவதற்கு முன் நடவடிக்கை எடுக்க உதவும்.",
    "Detected Anomaly Signals": "கண்டறியப்பட்ட ஒழுங்கின்மை சமிக்ஞைகள்",
