    "Click to Filter": "வடிகட்ட கிளிக் செய்க",
    "Monitor groundwater conditions, understand depletion risk, and make smarter crop decisions using groundwater, remote-sensing, weather, and hydro-agronomic intelligence.": "நிலத்தடி நீர் நிலைகளை கண்காணிக்கவும், நீர் பற்றாக்குறை அபாயத்தை புரிந்து கொள்ளவும், செயற்கைக்கோள், வானிலை மற்றும் வேளாண் நீர் நுண்ணறிவு மூலம் சிறந்த பயிர் முடிவுகளை எடுக்கவும்.",


