    "proactive_status_emerging": "\u0a89\u0aad\u0ab0\u0aa4\u0acb \u0a9c\u0acb\u0a96\u0aae \u0ab8\u0a82\u0a95\u0ac7\u0aa4",
    "proactive_status_recovery": "\u0ab0\u0abf\u0a9a\u0abe\u0ab0\u0acd\u0a9c \u0a85\u0aa8\u0ac7 \u0ab8\u0ac1\u0aa7\u0abe\u0ab0\u0aa3\u0abe \u0ab8\u0a82\u0a95\u0ac7\u0aa4",
    "proactive_status_data_quality": "\u0aa1\u0ac7\u0a9f\u0abe \u0a97\u0ac1\u0aa3\u0ab5\u0aa4\u0acd\u0aa4\u0abe \u0a9a\u0a95\u0abe\u0ab8\u0aa3\u0ac0 \u0a9c\u0ab0\u0ac2\u0ab0\u0ac0",
