    "All States": "બધા રાજ્યો",
    "Groundwater Early Warning Engine": "ભૂગર્ભજળ પ્રારંભિક ચેતવણી એન્જિન",
    "Groundwater Change & Data Quality Monitoring": "ભૂગર્ભજળ ફેરફાર અને ડેટા ગુણવત્તા મોનિટરિંગ",
    "Reference Simulation Data": "સંદર્ભ સિમ્યુલેશન ડેટા",
    "Groundwater Anomaly Detection & Early Warnings": "ભૂગર્ભજળ અસંગતતા શોધ અને પ્રારંભિક ચેતવણીઓ",
    "Detect unusual groundwater changes, distinguish possible water-level stress from sensor-quality issues, and identify areas that may need attention.": "અસામાન્ય ભૂગર્ભજળના ફેરફારો શોધો, પાણીના સ્તરના તણાવ અને સેન્સર ગુણવત્તાની સમસ્યાઓ વચ્ચેનો તફાવત સમજો અને ધ્યાન આપવા યોગ્ય વિસ્તારો ઓળખો.",
    "An unusual groundwater change can indicate increasing water stress, abnormal extraction, or a data-quality issue. Early review can help farmers and officials respond before water availability becomes a larger problem.": "અસામાન્ય ભૂગર્ભજળ ફેરફાર વધતા પાણીના તણાવ, અસામાન્ય ઉપાડ અથવા ડેટા-ગુણવત્તાની સમસ્યાનો સંકેત આપી શકે છે. સમયસર સમીક્ષા કરવાથી પરિસ્થિતિ ગંભીર બને તે પહેલાં પગલાં લેવામાં મદદ મળે છે.",
