    "Sensor / Hardware Status:": "સેન્સર / હાર્ડવેર સ્થિતિ:",
    "Observation Status": "અવલોકન સ્થિતિ",
    "Early Warning Signal": "પ્રારંભિક ચેતવણી સંકેત",
    "Understanding Groundwater Anomalies": "ભૂગર્ભજળની અસંગતતાઓને સમજવી",
    "Plain-language guide to groundwater early warning flags and data quality signals": "ભૂગર્ભજળ પ્રારંભિક ચેતવણી અને ડેટા ગુણવત્તા સંકેતો માટેની સરળ માર્ગદર્શિકા",
    "Water level falling faster than expected": "પાણીનું સ્તર અપેક્ષા કરતાં વધુ ઝડપથી ઘટી રહ્યું છે",
    "Groundwater level is falling faster than the expected local pattern. This may indicate concentrated pumping or rapid localized depletion.": "ભૂગર્ભજળનું સ્તર અપેક્ષિત સ્થાનિક પેટર્ન કરતાં વધુ ઝડપથી ઘટી રહ્યું છે. આ કેન્દ્રિત પમ્પિંગ અથવા ઝડપી સ્થાનિક ઘટાડો સૂચવી શકે છે.",
    "Repeated drawdown without normal recovery": "સામાન્ય રિકવરી વિના સતત ઘટાડો",
    "Repeated drawdown may indicate unusually high or sustained water withdrawal without the usual recharge window.": "રિચાર્જ વિન્ડો વિના વારંવાર થતો ઘટાડો અસામાન્ય રીતે ઊંચો અથવા સતત પાણીનો ઉપાડ સૂચવી શકે છે.",
    "Expected readings not received": "અપેક્ષિત રીડિંગ્સ મળ્યા નથી",
    "Expected observations are missing or arriving later than expected. Commonly caused by temporary network interruptions or power cycling.": "અપેક્ષિત અવલોકનો ખૂટે છે અથવા મોડા આવી રહ્યા છે. સામાન્ય રીતે કામચલાઉ નેટવર્ક સમસ્યાઓ અથવા પાવર સાઇકલિંગને કારણે થાય છે.",
    "Unusual reading patterns requiring check": "અસામાન્ય રીડિંગ પેટર્ન, ચકાસણી જરૂરી",
    "Readings show patterns that may require sensor or telemetry verification before drawing firm hydrogeological conclusions.": "નિષ્કર્ષ પર પહોંચતા પહેલાં સેન્સર અથવા ટેલિમેટ્રી ચકાસણીની જરૂર પડી શકે છે.",
    "Rapid water level increase": "પાણીના સ્તરમાં ઝડપી વધારો",
    "Groundwater level has increased sharply, potentially following heavy localized rainfall, canal release, or surface recharge.": "સ્થાનિક ભારે વરસાદ, કેનાલ છોડવા અથવા સપાટીના રિચાર્જને પગલે ભૂગર્ભજળના સ્તરમાં તીવ્ર વધારો થયો છે.",
    "Recommended Next Steps": "ભલામણ કરેલ આગલા પગલાં",
    "Actionable guidance for farmers and field officials when unusual signals are detected": "અસામાન્ય સંકેતો મળે ત્યારે ખેડૂતો અને ક્ષેત્રીય અધિકારીઓ માટે વ્યવહારુ માર્ગદર્શન",
    "Water Drop": "પાણી ઘટાડો",
    "Check Groundwater Forecast": "ભૂગર્ભજળની આગાહી તપાસો",
    "Review projected days-to-critical and consider adjusting pumping intervals or pump depth.": "અંદાજિત ગંભીર દિવસોની સમીક્ષા કરો અને પમ્પિંગ અંતરાલ અથવા પંપની ઊંડાઈને સમાયોજિત કરવાનું વિચારો.",
    "Inspect Neighboring Stations": "નજીકના સ્ટેશનોનું નિરીક્ષણ કરો",
    "Explore nearby monitoring stations on the map to determine whether the drop is localized or spread across the block.": "નકશા પર નજીકના સ્ટેશનો જુઓ જેથી જાણી શકાય કે ઘટાડો સ્થાનિક છે કે સમગ્ર બ્લોકમાં ફેલાયેલો છે.",
    "Data Quality": "ડેટા ગુણવત્તા",
    "Verify Latest Observations": "નવીનતમ અવલોકનો ચકાસો",
