    "Active in Middle Gangetic Basin (UP, Bihar, West Bengal) and Narmada Valley (MP). Shallow aquifers exhibit +0.3m to +0.5m post-monsoon water table recovery.": "મધ્ય ગંગા બેસિન (યુપી, બિહાર, પશ્ચિમ બંગાળ) અને નર્મદા ખીણ (એમપી) માં સક્રિય. છીછરા જળભંડારો ચોમાસા પછી +0.3m થી +0.5m પાણીના સ્તરમાં સુધારો દર્શાવે છે.",
    "Adopt mixed cropping (Maize + Pulses) to balance root-zone moisture draw.": "મૂળ વિસ્તારના ભેજનું સંતુલન જાળવવા મિશ્ર પાક પદ્ધતિ (મકાઈ + કઠોળ) અપનાવો.",
    "All values displayed are simulated DWLR data intended for model evaluation and operational planning. Future phases will integrate live CGWB REST telemetry endpoints and IMD meteorological grids.": "દર્શાવેલ તમામ મૂલ્યો મોડેલ મૂલ્યાંકન અને આયોજન માટે સિમ્યુલેટેડ DWLR ડેટા છે. ભવિષ્યના તબક્કામાં લાઇવ CGWB REST ટેલિમેટ્રી અને IMD હવામાન ગ્રીડ સંકલિત કરવામાં આવશે.",
    "Aquifer Rebound": "જળભંડાર સુધારો",
    "Aquifers Depleting < 30 Days": "30 દિવસથી ઓછા સમયમાં ખાલી થતા જળભંડારો",
    "Calculates 30-day moving average depletion slope (m/month) based on telemetry hydrostatic head pressure records.": "ટેલિમેટ્રી હાઇડ્રોસ્ટેટિક હેડ પ્રેશર રેકોર્ડ્સના આધારે 30-દિવસના મૂવિંગ એવરેજ ઘટાડા દર (મી/મહિનો) ની ગણતરી કરે છે.",
    "Clear silt from percolation tanks and farm recharge shafts.": "રિચાર્જ તળાવો અને ખેતરના બોરવેલ શાફ્ટમાંથી કાંપ સાફ કરો.",
    "Comparative state-level forecast trajectory, rainfall expectation, and agronomic priority actions": "તુલનાત્મક રાજ્ય-સ્તરીય આગાહી, વરસાદની અપેક્ષા અને કૃષિ પ્રાથમિકતાના પગલાં",
    "Concentrated in North-Western alluvial plains (Punjab, Haryana, Rajasthan) and hard-rock peninsular pockets (Kolar, Anantapur). Requires immediate crop substitution and night pumping schedules.": "ઉત્તર-પશ્ચિમના મેદાનો (પંજાબ, હરિયાણા, રાજસ્થાન) અને દ્વીપકલ્પ વિસ્તારો (કોલાર, અનંતપુર) માં કેન્દ્રિત. તાત્કાલિક પાક ફેરબદલ અને રાત્રિ પમ્પિંગ સમયપત્રક જરૂરી.",
