    "Days-to-critical estimates are calculated from current hydrostatic drawdown slope and historical monsoon infiltration response. Projections adapt dynamically as seasonal rainfall and pumping patterns change.": "ગંભીર દિવસોનો અંદાજ વર્તમાન જળસ્તર ઘટાડા દર અને ઐતિહાસિક ચોમાસાના આધારે લગાવવામાં આવે છે. વરસાદ અને પમ્પિંગ પેટર્ન મુજબ અંદાજ આપમેળે અપડેટ થાય છે.",
    "Estimated as (Current Depth - Critical Threshold) / Daily Depletion Rate, bounded by seasonal rainfall recharge coefficients.": "(વર્તમાન ઊંડાઈ - ગંભીર મર્યાદા) / દૈનિક ઘટાડા દર તરીકે અંદાજિત, જે મોસમી વરસાદના રિચાર્જ પરિબળો દ્વારા મર્યાદિત છે.",
