    "Detect unusual groundwater changes, distinguish possible water-level stress from sensor-quality issues, and identify areas that may need attention.": "ಅಸಹಜ ಅಂತರ್ಜಲ ಬದಲಾವಣೆಗಳನ್ನು ಗುರುತಿಸಿ, ನೀರಿನ ಮಟ್ಟದ ಒತ್ತಡ ಮತ್ತು ಸೆನ್ಸರ್ ಗುಣಮಟ್ಟದ ಸಮಸ್ಯೆಗಳ ನಡುವಿನ ವ್ಯತ್ಯಾಸವನ್ನು ತಿಳಿದುಕೊಳ್ಳಿ ಮತ್ತು ಗಮನಹರಿಸಬೇಕಾದ ಪ್ರದೇಶಗಳನ್ನು ಗುರುತಿಸಿ.",
    "An unusual groundwater change can indicate increasing water stress, abnormal extraction, or a data-quality issue. Early review can help farmers and officials respond before water availability becomes a larger problem.": "ಅಸಹಜ ಅಂತರ್ಜಲ ಬದಲಾವಣೆಯು ಹೆಚ್ಚುತ್ತಿರುವ ನೀರಿನ ಒತ್ತಡ, ಅತಿಯಾದ ಬಳಕೆ ಅಥವಾ ಡೇಟಾ ಗುಣಮಟ್ಟದ ಸಮಸ್ಯೆಯನ್ನು ಸೂಚಿಸಬಹುದು. ಮುಂಚಿತವಾಗಿ ಪರಿಶೀಲಿಸುವುದರಿಂದ ಸಮಸ್ಯೆ ಉಲ್ಬಣಗೊಳ್ಳುವ ಮೊದಲೇ ಕ್ರಮ ಕೈಗೊಳ್ಳಲು ನೆರವಾಗುತ್ತದೆ.",
    "Detected Anomaly Signals": "ಪತ್ತೆಯಾದ ಅಸಹಜ ಸಂಕೇತಗಳು",
    "Anomaly Signals": "ಅಸಹಜ ಸಂಕೇತಗಳು",
