    "Sudden Groundwater Drop": "ಹಠಾತ್ ಅಂತರ್ಜಲ ಕುಸಿತ",
    "Groundwater level is falling faster than the expected local pattern.": "ಅಂತರ್ಜಲ ಮಟ್ಟವು ಸ್ಥಳೀಯ ನಿರೀಕ್ಷಿತ ಮಟ್ಟಕ್ಕಿಂತ ವೇಗವಾಗಿ ಇಳಿಯುತ್ತಿದೆ.",
