    "Possible Sensor Data Issue": "ಸಾಧ್ಯವಿರುವ ಸೆನ್ಸರ್ ಡೇಟಾ ಸಮಸ್ಯೆ",
    "Readings show patterns that may require sensor or telemetry verification.": "ರೀಡಿಂಗ್‌ಗಳು ಸೆನ್ಸರ್ ಅಥವಾ ಟೆಲಿಮೆಟ್ರಿ ಪರಿಶೀಲನೆ ಅಗತ್ಯವಿರುವ ಮಾದರಿಗಳನ್ನು ತೋರಿಸುತ್ತಿವೆ.",
    "Sudden Groundwater Rise": "ಹಠಾತ್ ಅಂತರ್ಜಲ ಏರಿಕೆ",
    "Groundwater level has increased sharply, potentially following rainfall or recharge conditions.": "ಮಳೆ ಅಥವಾ ಮರುಪೂರಣದ ಪರಿಸ್ಥಿತಿಗಳಿಂದಾಗಿ ಅಂತರ್ಜಲ ಮಟ್ಟವು ಗಣನೀಯವಾಗಿ ಹೆಚ್ಚಾಗಿದೆ.",
    "Recent Groundwater & Data Quality Signals": "ಇತ್ತೀಚಿನ ಅಂತರ್ಜಲ ಮತ್ತು ಡೇಟಾ ಗುಣಮಟ್ಟದ ಸಂಕೇತಗಳು",
    "Critical (Immediate Attention)": "ಗಂಭೀರ (ತಕ್ಷಣದ ಗಮನ)",
    "High (Review Soon)": "ಹೆಚ್ಚಿನ (ಶೀಘ್ರದಲ್ಲೇ ಪರಿಶೀಲಿಸಿ)",
