    "Data Quality / Low (Verify)": "ಡೇಟಾ ಗುಣಮಟ್ಟ / ಕಡಿಮೆ (ಪರಿಶೀಲಿಸಿ)",
    "Why Flagged / Insight:": "ಎಚ್ಚರಿಕೆಯ ಕಾರಣ / ಒಳನೋಟ:",
    "Plain-Language Assessment": "ಸರಳ ಭಾಷೆಯ ಮೌಲ್ಯಮಾಪನ",
    "Recommended Follow-up Action": "ಶಿಫಾರಸು ಮಾಡಿದ ಮುಂದಿನ ಕ್ರಮ",
    "Technical Evidence & Telemetry Details": "ತಾಂತ್ರಿಕ ಪುರಾವೆ ಮತ್ತು ಟೆಲಿಮೆಟ್ರಿ ವಿವರಗಳು",
    "Observation Timeline vs Expected Baseline": "ವೀಕ್ಷಣೆ ಕಾಲಮಿತಿ ಮತ್ತು ನಿರೀಕ್ಷಿತ ಬೇಸ್‌ಲೈನ್",
    "Sensor / Hardware Status:": "ಸೆನ್ಸರ್ / ಹಾರ್ಡ್‌ವೇರ್ ಸ್ಥಿತಿ:",
    "Observation Status": "ವೀಕ್ಷಣೆ ಸ್ಥಿತಿ",
    "Early Warning Signal": "ಮುನ್ಸೂಚನೆ ಸಂಕೇತ",
    "Understanding Groundwater Anomalies": "ಅಂತರ್ಜಲ ಅಸಹಜತೆಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳುವುದು",
    "Plain-language guide to groundwater early warning flags and data quality signals": "ಅಂತರ್ಜಲ ಮುನ್ಸೂಚನೆ ಮತ್ತು ಡೇಟಾ ಗುಣಮಟ್ಟದ ಸಂಕೇತಗಳ ಸರಳ ಮಾರ್ಗದರ್ಶಿ",
    "Water level falling faster than expected": "ನೀರಿನ ಮಟ್ಟವು ನಿರೀಕ್ಷೆಗಿಂತ ವೇಗವಾಗಿ ಇಳಿಯುತ್ತಿದೆ",
    "Groundwater level is falling faster than the expected local pattern. This may indicate concentrated pumping or rapid localized depletion.": "ಅಂತರ್ಜಲ ಮಟ್ಟವು ಸ್ಥಳೀಯ ನಿರೀಕ್ಷೆಗಿಂತ ವೇಗವಾಗಿ ಇಳಿಯುತ್ತಿದೆ. ಇದು ಅತಿಯಾದ ಪಂಪಿಂಗ್ ಅಥವಾ ವೇಗದ ಸ್ಥಳೀಯ ಇಳಿಕೆಯನ್ನು ಸೂಚಿಸಬಹುದು.",
    "Repeated drawdown without normal recovery": "ಸಾಮಾನ್ಯ ಚೇತರಿಕೆಯಿಲ್ಲದೆ ನಿರಂತರ ಇಳಿಕೆ",
    "Repeated drawdown may indicate unusually high or sustained water withdrawal without the usual recharge window.": "ಸಾಮಾನ್ಯ ಮರುಪೂರಣವಿಲ್ಲದೆ ಪುನರಾವರ್ತಿತ ಇಳಿಕೆಯು ಅತಿಯಾದ ಅಥವಾ ನಿರಂತರ ನೀರಿನ ಬಳಕೆಯನ್ನು ಸೂಚಿಸಬಹುದು.",
    "Expected readings not received": "ನಿರೀಕ್ಷಿತ ರೀಡಿಂಗ್‌ಗಳು ಬಂದಿಲ್ಲ",
    "Expected observations are missing or arriving later than expected. Commonly caused by temporary network interruptions or power cycling.": "ನಿರೀಕ್ಷಿತ ವೀಕ್ಷಣೆಗಳು ಅಲಭ್ಯವಾಗಿವೆ ಅಥವಾ ತಡವಾಗಿ ಬರುತ್ತಿವೆ. ಇದು ಸಾಮಾನ್ಯವಾಗಿ ತಾತ್ಕಾಲಿಕ ನೆಟ್‌ವರ್ಕ್ ಸಮಸ್ಯೆಗಳಿಂದ ಉಂಟಾಗುತ್ತದೆ.",
    "Unusual reading patterns requiring check": "ಅಸಹಜ ರೀಡಿಂಗ್ ಮಾದರಿಗಳು, ತಪಾಸಣೆ ಅಗತ್ಯವಿದೆ",
    "Readings show patterns that may require sensor or telemetry verification before drawing firm hydrogeological conclusions.": "ಅಂತಿಮ ತೀರ್ಮಾನಕ್ಕೆ ಬರುವ ಮೊದಲು ಸೆನ್ಸರ್ ಅಥವಾ ಟೆಲಿಮೆಟ್ರಿ ಪರಿಶೀಲನೆ ಅಗತ್ಯವಿರುವ ಮಾದರಿಗಳನ್ನು ರೀಡಿಂಗ್‌ಗಳು ತೋರಿಸುತ್ತಿವೆ.",
    "Rapid water level increase": "ನೀರಿನ ಮಟ್ಟದಲ್ಲಿ ತ್ವರಿತ ಏರಿಕೆ",
    "Groundwater level has increased sharply, potentially following heavy localized rainfall, canal release, or surface recharge.": "ಸ್ಥಳೀಯ ಭಾರಿ ಮಳೆ, ಕಾಲುವೆ ನೀರು ಅಥವಾ ಮೇಲ್ಮೈ ಮರುಪೂರಣದಿಂದಾಗಿ ಅಂತರ್ಜಲ ಮಟ್ಟವು ತೀವ್ರವಾಗಿ ಹೆಚ್ಚಾಗಿದೆ.",
    "Recommended Next Steps": "ಶಿಫಾರಸು ಮಾಡಿದ ಮುಂದಿನ ಹಂತಗಳು",
    "Actionable guidance for farmers and field officials when unusual signals are detected": "ಅಸಹಜ ಸಂಕೇತಗಳು ಕಂಡುಬಂದಾಗ ರೈತರು ಮತ್ತು ಅಧಿಕಾರಿಗಳಿಗೆ ಕ್ರಿಯಾಶೀಲ ಮಾರ್ಗದರ್ಶನ",
    "Water Drop": "ನೀರಿನ ಕುಸಿತ",
    "Check Groundwater Forecast": "ಅಂತರ್ಜಲ ಮುನ್ಸೂಚನೆ ಪರಿಶೀಲಿಸಿ",
    "Review projected days-to-critical and consider adjusting pumping intervals or pump depth.": "ಅಂದಾಜು ನಿರ್ಣಾಯಕ ದಿನಗಳನ್ನು ಪರಿಶೀಲಿಸಿ ಮತ್ತು ಪಂಪಿಂಗ್ ಅವಧಿಯನ್ನು ಸರಿಹೊಂದಿಸುವುದನ್ನು ಪರಿಗಣಿಸಿ.",
