    "Recharge Potential Index": "ಮರುಪೂರಣ ಸಾಮರ್ಥ್ಯ ಸೂಚ್ಯಂಕ",

    "1. Drawdown Velocity Model": "1. ಅಂತರ್ಜಲ ಇಳಿಕೆ ವೇಗ ಮಾದರಿ",
    "2. Days-to-Critical Threshold": "2. ನಿರ್ಣಾಯಕ ಮಿತಿಗೆ ಉಳಿದಿರುವ ದಿನಗಳು",
    "3. Uncertainty & Confidence Envelope": "3. ಅನಿಶ್ಚಿತತೆ ಮತ್ತು ವಿಶ್ವಾಸಾರ್ಹತೆಯ ವ್ಯಾಪ್ತಿ",
    "4. Data Disclaimer": "4. ಡೇಟಾ ಹಕ್ಕು ನಿರಾಕರಣೆ",
    "30-day precipitation projections (mm) vs normal baseline and calculated infiltration recharge potential": "ಸಾಮಾನ್ಯ ಮಟ್ಟಕ್ಕೆ ಹೋಲಿಸಿದರೆ 30 ದಿನಗಳ ಮಳೆ ಮುನ್ಸೂಚನೆ (ಮಿಮೀ) ಮತ್ತು ಅಂತರ್ಜಲ ಮರುಪೂರಣ ಸಾಮರ್ಥ್ಯ",
    "30d Projected": "30 ದಿನಗಳ ಅಂದಾಜು",
    "30–60 Days": "30–60 ದಿನಗಳು",
    "60+ Days": "60+ ದಿನಗಳು",
    "90-Day Forecast Direction": "90 ದಿನಗಳ ಮುನ್ಸೂಚನೆ ದಿಕ್ಕು",
    "Active Deficit": "ಸಕ್ರಿಯ ಕೊರತೆ",
    "Active in Middle Gangetic Basin (UP, Bihar, West Bengal) and Narmada Valley (MP). Shallow aquifers exhibit +0.3m to +0.5m post-monsoon water table recovery.": "ಮಧ್ಯ ಗಂಗಾ ಜಲಾನಯನ ಪ್ರದೇಶ (ಯುಪಿ, ಬಿಹಾರ, ಪಶ್ಚಿಮ ಬಂಗಾಳ) ಮತ್ತು ನರ್ಮದಾ ಕಣಿವೆಯಲ್ಲಿ (ಎಂಪಿ) ಸಕ್ರಿಯವಾಗಿದೆ. ಆಳವಿಲ್ಲದ ಜಲಚರಗಳು ಮಾನ್ಸೂನ್ ನಂತರ +0.3 ಮೀ ನಿಂದ +0.5 ಮೀ ವರೆಗೆ ಜಲಮಟ್ಟ ಸುಧಾರಣೆ ತೋರಿಸುತ್ತವೆ.",
    "Adopt mixed cropping (Maize + Pulses) to balance root-zone moisture draw.": "ಬೇರು ವಲಯದ ತೇವಾಂಶವನ್ನು ಸಮತೋಲನಗೊಳಿಸಲು ಮಿಶ್ರ ಬೆಳೆ ಪದ್ಧತಿಯನ್ನು (ಮೆಕ್ಕೆಜೋಳ + ಬೇಳೆಕಾಳುಗಳು) ಅಳವಡಿಸಿಕೊಳ್ಳಿ.",
    "All values displayed are simulated DWLR data intended for model evaluation and operational planning. Future phases will integrate live CGWB REST telemetry endpoints and IMD meteorological grids.": "ಪ್ರದರ್ಶಿಸಲಾದ ಎಲ್ಲಾ ಮೌಲ್ಯಗಳು ಮಾದರಿ ಮೌಲ್ಯಮಾಪನ ಮತ್ತು ಯೋಜನೆಗಾಗಿ ಸಿಮ್ಯುಲೇಟೆಡ್ DWLR ಡೇಟಾ ಆಗಿದೆ. ಭವಿಷ್ಯದ ಹಂತಗಳಲ್ಲಿ ಲೈವ್ CGWB REST ಟೆಲಿಮೆಟ್ರಿ ಮತ್ತು IMD ಹವಾಮಾನ ಗ್ರಿಡ್‌ಗಳನ್ನು ಸಂಯೋಜಿಸಲಾಗುವುದು.",
    "Aquifer Rebound": "ಅಂತರ್ಜಲ ಮರುಪೂರಣ",
    "Aquifers Depleting < 30 Days": "30 ದಿನಗಳಿಗಿಂತ ಕಡಿಮೆ ಅವಧಿಯಲ್ಲಿ ಬರಿದಾಗುತ್ತಿರುವ ಅಂತರ್ಜಲ",
    "Calculates 30-day moving average depletion slope (m/month) based on telemetry hydrostatic head pressure records.": "ಟೆಲಿಮೆಟ್ರಿ ಹೈಡ್ರೋಸ್ಟಾಟಿಕ್ ಹೆಡ್ ಒತ್ತಡದ ದಾಖಲೆಗಳ ಆಧಾರದ ಮೇಲೆ 30 ದಿನಗಳ ಸರಾಸರಿ ಇಳಿಕೆ ದರವನ್ನು (ಮೀ/ತಿಂಗಳು) ಲೆಕ್ಕಾಚಾರ ಮಾಡುತ್ತದೆ.",
    "Clear silt from percolation tanks and farm recharge shafts.": "ಇಂಗು ಗುಂಡಿಗಳು ಮತ್ತು ಜಮೀನಿನ ಮರುಪೂರಣ ಶಾಫ್ಟ್‌ಗಳಿಂದ ಹೂಳನ್ನು ತೆಗೆಯಿರಿ.",
    "Comparative state-level forecast trajectory, rainfall expectation, and agronomic priority actions": "ತುಲನಾತ್ಮಕ ರಾಜ್ಯ ಮಟ್ಟದ ಮುನ್ಸೂಚನೆ, ಮಳೆಯ ನಿರೀಕ್ಷೆ ಮತ್ತು ಆದ್ಯತೆಯ ಕೃಷಿ ಕ್ರಮಗಳು",
    "Concentrated in North-Western alluvial plains (Punjab, Haryana, Rajasthan) and hard-rock peninsular pockets (Kolar, Anantapur). Requires immediate crop substitution and night pumping schedules.": "ವಾಯುವ್ಯ ಬಯಲು ಪ್ರದೇಶಗಳು (ಪಂಜಾಬ್, ಹರಿಯಾಣ, ರಾಜಸ್ಥಾನ) ಮತ್ತು ಪರ್ಯಾಯ ದ್ವೀಪ ಪ್ರದೇಶಗಳಲ್ಲಿ (ಕೋಲಾರ, ಅನಂತಪುರ) ಕೇಂದ್ರೀಕೃತವಾಗಿದೆ. ತಕ್ಷಣದ ಬೆಳೆ ಬದಲಾವಣೆ ಮತ್ತು ರಾತ್ರಿ ಪಂಪಿಂಗ್ ಅಗತ್ಯವಿದೆ.",
    "Confidence": "ವಿಶ್ವಾಸಾರ್ಹತೆ",
    "Crop Rotation": "ಬೆಳೆ ಪರಿವರ್ತನೆ",
    "Crop Switch": "ಬೆಳೆ ಬದಲಾವಣೆ",
