    "Days-to-critical estimates are calculated from current hydrostatic drawdown slope and historical monsoon infiltration response. Projections adapt dynamically as seasonal rainfall and pumping patterns change.": "ನಿರ್ಣಾಯಕ ದಿನಗಳ ಅಂದಾಜನ್ನು ಪ್ರಸ್ತುತ ಅಂತರ್ಜಲ ಇಳಿಕೆ ದರ ಮತ್ತು ಹಿಂದಿನ ಮಾನ್ಸೂನ್ ಮರುಪೂರಣದ ಆಧಾರದ ಮೇಲೆ ಲೆಕ್ಕಹಾಕಲಾಗುತ್ತದೆ. ಮಳೆ ಮತ್ತು ಪಂಪಿಂಗ್ ಆಧಾರದ ಮೇಲೆ ಅಂದಾಜುಗಳು ಬದಲಾಗುತ್ತವೆ.",
    "Estimated as (Current Depth - Critical Threshold) / Daily Depletion Rate, bounded by seasonal rainfall recharge coefficients.": "(ಪ್ರಸ್ತುತ ಆಳ - ನಿರ್ಣಾಯಕ ಮಿತಿ) / ದೈನಂದಿನ ಇಳಿಕೆ ದರ ಎಂದು ಅಂದಾಜಿಸಲಾಗಿದೆ, ಇದು ಕಾಲೋಚಿತ ಮಳೆ ಮರುಪೂರಣ ಗುಣಾಂಕಗಳಿಂದ ಸೀಮಿತವಾಗಿದೆ.",
