    "Stay alert for sudden pumping anomalies during peak flowering.": "ಹೂ ಬಿಡುವ ಸಮಯದಲ್ಲಿ ಹಠಾತ್ ಪಂಪಿಂಗ್ ವ್ಯತ್ಯಾಸಗಳ ಬಗ್ಗೆ ಎಚ್ಚರದಿಂದಿರಿ.",
    "Strict deficit irrigation. Run tube-wells only at night to reduce evaporation loss.": "ಕಟ್ಟುನಿಟ್ಟಾದ ನಿಯಂತ್ರಿತ ನೀರಾವರಿ ಪದ್ಧತಿ ಅನುಸರಿಸಿ. ಆವಿಯಾಗುವಿಕೆಯನ್ನು ಕಡಿಮೆ ಮಾಡಲು ರಾತ್ರಿ ವೇಳೆ ಮಾತ್ರ ಕೊಳವೆಬಾವಿಗಳನ್ನು ಚಲಾಯಿಸಿ.",
