    "An unusual groundwater change can indicate increasing water stress, abnormal extraction, or a data-quality issue. Early review can help farmers and officials respond before water availability becomes a larger problem.": "അസാധാരണമായ ഭൂഗർഭജല മാറ്റം വർദ്ധിച്ചുവരുന്ന ജലക്ഷാമം, അമിത ഉപയോഗം അല്ലെങ്കിൽ ഡാറ്റാ ഗുണനിലവാര പ്രശ്നം എന്നിവയെ സൂചിപ്പിക്കാം. നേരത്തെയുള്ള പരിശോധന ജലലഭ്യത പ്രതിസന്ധിയാകുന്നതിന് മുൻപ് നടപടിയെടുക്കാൻ സഹായിക്കും.",
