    "Understanding Groundwater Anomalies": "ഭൂഗർഭജല അപാകതകൾ മനസ്സിലാക്കുക",
    "Plain-language guide to groundwater early warning flags and data quality signals": "ഭൂഗർഭജല മുൻകൂർ മുന്നറിയിപ്പുകളും ഡാറ്റാ ഗുണനിലവാര സൂചനകളും സംബന്ധിച്ച ലളിതമായ സഹായി",
    "Water level falling faster than expected": "ജലനിരപ്പ് പ്രതീക്ഷിച്ചതിലും വേഗത്തിൽ താഴുന്നു",
    "Groundwater level is falling faster than the expected local pattern. This may indicate concentrated pumping or rapid localized depletion.": "ഭൂഗർഭജല നിരപ്പ് പ്രതീക്ഷിച്ചതിലും വേഗത്തിൽ താഴുന്നു. ഇത് അമിതമായ പമ്പിംഗ് അല്ലെങ്കിൽ പെട്ടെന്നുള്ള ജലക്ഷാമത്തെ സൂചിപ്പിക്കാം.",
    "Repeated drawdown without normal recovery": "സാധാരണ വീണ്ടെടുക്കലില്ലാതെ തുടർച്ചയായ കുറവ്",
    "Repeated drawdown may indicate unusually high or sustained water withdrawal without the usual recharge window.": "സാധാരണ റീചാർജ് ഇല്ലാതെ തുടർച്ചയായി കുറയുന്നത് അമിതമായ ജല ഉപഭോഗത്തെ സൂചിപ്പിക്കാം.",
    "Expected readings not received": "പ്രതീക്ഷിച്ച റീഡിംഗുകൾ ലഭിച്ചില്ല",
    "Expected observations are missing or arriving later than expected. Commonly caused by temporary network interruptions or power cycling.": "പ്രതീക്ഷിച്ച നിരീക്ഷണങ്ങൾ ലഭ്യമല്ല അല്ലെങ്കിൽ വൈകുന്നു. സാധാരണയായി നെറ്റ്‌വർക്ക് തകരാറുകൾ മൂലമാണ് ഇത് സംഭവിക്കുന്നത്.",
    "Unusual reading patterns requiring check": "അസാധാരണ റീഡിംഗുകൾ, പരിശോധന ആവശ്യമാണ്",
    "Readings show patterns that may require sensor or telemetry verification before drawing firm hydrogeological conclusions.": "തീരുമാനങ്ങളിൽ എത്തുന്നതിന് മുമ്പ് സെൻസർ അല്ലെങ്കിൽ ടെലിമെട്രി പരിശോധന ആവശ്യമായേക്കാം.",
    "Rapid water level increase": "ജലനിരപ്പിൽ ദ്രുതഗതിയിലുള്ള വർദ്ധനവ്",
    "Groundwater level has increased sharply, potentially following heavy localized rainfall, canal release, or surface recharge.": "കനത്ത മഴ, കനാൽ ജലം അല്ലെങ്കിൽ ഉപരിതല റീചാർജ് എന്നിവയെ തുടർന്ന് ഭൂഗർഭജല നിരപ്പ് കുത്തനെ വർദ്ധിച്ചു.",
    "Recommended Next Steps": "ശുപാർശ ചെയ്യുന്ന അടുത്ത ഘട്ടങ്ങൾ",
