    "Explore nearby monitoring stations on the map to determine whether the drop is localized or spread across the block.": "കുറവ് ഒരു പ്രത്യേക സ്ഥലത്താണോ അതോ ബ്ലോക്ക് മുഴുവനുമുണ്ടോ എന്ന് അറിയാൻ മാപ്പിലെ സമീപ സ്റ്റേഷനുകൾ കാണുക.",
