    "Recharge Potential Index": "റീചാർജ് സാധ്യത സൂചിക",

    "1. Drawdown Velocity Model": "1. ഭൂഗർഭജല താഴ്ച വേഗത മോഡൽ",
    "2. Days-to-Critical Threshold": "2. നിർണായക പരിധിയിലേക്ക് ബാക്കിയുള്ള ദിവസങ്ങൾ",
    "3. Uncertainty & Confidence Envelope": "3. അനിശ്ചിതത്വവും വിശ്വാസ്യത പരിധിയും",
    "4. Data Disclaimer": "4. ഡാറ്റ നിരാകരണം",
    "30-day precipitation projections (mm) vs normal baseline and calculated infiltration recharge potential": "സാധാരണ അളവിനെ അപേക്ഷിച്ച് 30 ദിവസത്തെ മഴ പ്രവചനവും (എംഎം) കണക്കാക്കിയ റീചാർജ് സാധ്യതയും",
    "30d Projected": "30 ദിവസത്തെ പ്രവചനം",
    "30–60 Days": "30–60 ദിവസങ്ങൾ",
    "60+ Days": "60+ ദിവസങ്ങൾ",
    "90-Day Forecast Direction": "90 ദിവസത്തെ പ്രവചന ദിശ",
    "Active Deficit": "സജീവ കമ്മി",
    "Active in Middle Gangetic Basin (UP, Bihar, West Bengal) and Narmada Valley (MP). Shallow aquifers exhibit +0.3m to +0.5m post-monsoon water table recovery.": "മധ്യ ഗംഗാ തടത്തിലും (യുപി, ബിഹാർ, പശ്ചിമ ബംഗാൾ) നർമ്മദ താഴ്‌വരയിലും (എംപി) സജീവം. ആഴം കുറഞ്ഞ അക്വിഫറുകൾ മൺസൂണിന് ശേഷം +0.3 മീറ്റർ മുതൽ +0.5 മീറ്റർ വരെ ജലനിരപ്പ് വീണ്ടെടുക്കൽ കാണിക്കുന്നു.",
    "Adopt mixed cropping (Maize + Pulses) to balance root-zone moisture draw.": "വേരുകളുടെ ഭാഗത്തെ ഈർപ്പം സന്തുലിതമാക്കാൻ മിശ്രിത വിള കൃഷി (ചോളം + പയറുവർഗ്ഗങ്ങൾ) സ്വീകരിക്കുക.",
    "All values displayed are simulated DWLR data intended for model evaluation and operational planning. Future phases will integrate live CGWB REST telemetry endpoints and IMD meteorological grids.": "പ്രദർശിപ്പിച്ചിരിക്കുന്ന എല്ലാ മൂല്യങ്ങളും മോഡൽ മൂല്യനിർണ്ണയത്തിനും ആസൂത്രണത്തിനുമുള്ള സിമുലേറ്റഡ് DWLR ഡാറ്റയാണ്. ഭാവി ഘട്ടങ്ങളിൽ തത്സമയ CGWB REST ടെലിമെട്രിയും IMD കാലാവസ്ഥാ ഗ്രിഡുകളും സംയോജിപ്പിക്കും.",
    "Aquifer Rebound": "അക്വിഫർ വീണ്ടെടുക്കൽ",
    "Aquifers Depleting < 30 Days": "30 ദിവസത്തിൽ താഴെ കൊണ്ട് വറ്റുന്ന അക്വിഫറുകൾ",
    "Calculates 30-day moving average depletion slope (m/month) based on telemetry hydrostatic head pressure records.": "ടെലിമെട്രി ഹൈഡ്രോസ്റ്റാറ്റിക് ഹെഡ് പ്രഷർ രേഖകളെ അടിസ്ഥാനമാക്കി 30 ദിവസത്തെ ശരാശരി താഴ്ച നിരക്ക് (മീ/മാസം) കണക്കാക്കുന്നു.",
    "Clear silt from percolation tanks and farm recharge shafts.": "റീചാർജ് കുളങ്ങളിൽ നിന്നും ഷാഫ്റ്റുകളിൽ നിന്നും ചെളി നീക്കം ചെയ്യുക.",
    "Comparative state-level forecast trajectory, rainfall expectation, and agronomic priority actions": "താരതമ്യ സംസ്ഥാനതല പ്രവചനം, മഴ പ്രതീക്ഷ, മുൻഗണനാ കാർഷിക നടപടികൾ",
    "Concentrated in North-Western alluvial plains (Punjab, Haryana, Rajasthan) and hard-rock peninsular pockets (Kolar, Anantapur). Requires immediate crop substitution and night pumping schedules.": "വടക്ക്-പടിഞ്ഞാറൻ സമതലങ്ങളിലും (പഞ്ചാബ്, ഹരിയാന, രാജസ്ഥാൻ) ഉപദ്വീപിലെ പാറക്കെട്ടുകളുള്ള പ്രദേശങ്ങളിലും (കോലാർ, അനന്തപുർ) കേന്ദ്രീകരിച്ചിരിക്കുന്നു. ഉടനടി വിള മാറ്റവും രാത്രി പമ്പിംഗും ആവശ്യമാണ്.",
    "Confidence": "വിശ്വാസ്യത",
    "Crop Rotation": "വിള പരിക്രമണം",
    "Crop Switch": "വിള മാറ്റം",
    "Cumulative Change": "ആകെ മാറ്റം",
    "Current Avg Depth": "നിലവിലെ ശരാശരി ആഴം",
    "Current Trend": "നിലവിലെ പ്രവണത",
