    "Days-to-critical estimates are calculated from current hydrostatic drawdown slope and historical monsoon infiltration response. Projections adapt dynamically as seasonal rainfall and pumping patterns change.": "നിർണായക ദിവസങ്ങളുടെ കണക്കുകൂട്ടൽ നിലവിലെ ജലനിരപ്പ് താഴ്ചയും ചരിത്രപരമായ മൺസൂൺ റീചാർജും അടിസ്ഥാനമാക്കിയുള്ളതാണ്. മഴയ്ക്കും പമ്പിംഗിനും അനുസരിച്ച് പ്രവചനങ്ങൾ മാറുന്നു.",
    "Estimated as (Current Depth - Critical Threshold) / Daily Depletion Rate, bounded by seasonal rainfall recharge coefficients.": "(നിലവിലെ ആഴം - നിർണായക പരിധി) / പ്രതിദിന താഴ്ച നിരക്ക് എന്ന് കണക്കാക്കുന്നു, ഇത് കാലാനുസൃതമായ മഴ റീചാർജ് ഗുണകങ്ങളാൽ പരിമിതപ്പെടുത്തിയിരിക്കുന്നു.",
