    "Groundwater level is falling faster than the expected local pattern.": "ਧਰਤੀ ਹੇਠਲੇ ਪਾਣੀ ਦਾ ਪੱਧਰ ਸਥਾਨਕ ਉਮੀਦ ਨਾਲੋਂ ਤੇਜ਼ੀ ਨਾਲ ਡਿੱਗ ਰਿਹਾ ਹੈ।",
