    "Recharge Potential Index": "ਰੀਚਾਰਜ ਸਮਰੱਥਾ ਸੂਚਕਾਂਕ",

    "1. Drawdown Velocity Model": "1. ਪਾਣੀ ਦਾ ਪੱਧਰ ਡਿੱਗਣ ਦੀ ਦਰ ਮਾਡਲ",
    "2. Days-to-Critical Threshold": "2. ਗੰਭੀਰ ਸੀਮਾ ਤੱਕ ਬਾਕੀ ਦਿਨ",
    "3. Uncertainty & Confidence Envelope": "3. ਅਨਿਸ਼ਚਿਤਤਾ ਅਤੇ ਵਿਸ਼ਵਾਸ ਦਾ ਘੇਰਾ",
    "4. Data Disclaimer": "4. ਡਾਟਾ ਬੇਦਾਅਵਾ",
    "30-day precipitation projections (mm) vs normal baseline and calculated infiltration recharge potential": "ਆਮ ਪੱਧਰ ਦੇ ਮੁਕਾਬਲੇ 30-ਦਿਨਾਂ ਦੀ ਬਾਰਿਸ਼ ਦਾ ਅੰਦਾਜ਼ਾ (ਮਿਮੀ) ਅਤੇ ਜ਼ਮੀਨਦੋਜ਼ ਰੀਚਾਰਜ ਸਮਰੱਥਾ",
    "30d Projected": "30 ਦਿਨਾਂ ਦਾ ਅੰਦਾਜ਼ਾ",
    "30–60 Days": "30–60 ਦਿਨ",
    "60+ Days": "60+ ਦਿਨ",
    "90-Day Forecast Direction": "90-ਦਿਨਾਂ ਦੀ ਭਵਿੱਖਬਾਣੀ ਦਿਸ਼ਾ",
    "Active Deficit": "ਸਰਗਰਮ ਘਾਟਾ",
    "Active in Middle Gangetic Basin (UP, Bihar, West Bengal) and Narmada Valley (MP). Shallow aquifers exhibit +0.3m to +0.5m post-monsoon water table recovery.": "ਮੱਧ ਗੰਗਾ ਬੇਸਿਨ (ਯੂਪੀ, ਬਿਹਾਰ, ਪੱਛਮੀ ਬੰਗਾਲ) ਅਤੇ ਨਰਮਦਾ ਘਾਟੀ (ਐਮਪੀ) ਵਿੱਚ ਸਰਗਰਮ। ਮਾਨਸੂਨ ਤੋਂ ਬਾਅਦ ਪਾਣੀ ਦਾ ਪੱਧਰ +0.3 ਮੀਟਰ ਤੋਂ +0.5 ਮੀਟਰ ਤੱਕ ਸੁਧਰਦਾ ਹੈ।",
    "Adopt mixed cropping (Maize + Pulses) to balance root-zone moisture draw.": "ਜੜ੍ਹਾਂ ਵਿੱਚ ਨਮੀ ਦਾ ਸੰਤੁਲਨ ਬਣਾਉਣ ਲਈ ਮਿਸ਼ਰਤ ਫਸਲੀ ਪ੍ਰਣਾਲੀ (ਮੱਕੀ + ਦਾਲਾਂ) ਅਪਣਾਓ।",
    "All values displayed are simulated DWLR data intended for model evaluation and operational planning. Future phases will integrate live CGWB REST telemetry endpoints and IMD meteorological grids.": "ਦਿਖਾਏ ਗਏ ਸਾਰੇ ਮੁੱਲ ਮਾਡਲ ਮੁਲਾਂਕਣ ਅਤੇ ਯੋਜਨਾਬੰਦੀ ਲਈ ਸਿਮੂਲੇਟਡ DWLR ਡਾਟਾ ਹਨ। ਭਵਿੱਖ ਦੇ ਪੜਾਵਾਂ ਵਿੱਚ ਲਾਈਵ CGWB REST ਟੈਲੀਮੈਟਰੀ ਅਤੇ IMD ਮੌਸਮ ਗਰਿੱਡ ਸ਼ਾਮਲ ਕੀਤੇ ਜਾਣਗੇ।",
    "Aquifer Rebound": "ਜਲ ਸਰੋਤ ਸੁਧਾਰ",
    "Aquifers Depleting < 30 Days": "30 ਦਿਨਾਂ ਤੋਂ ਘੱਟ ਸਮੇਂ ਵਿੱਚ ਖਤਮ ਹੋ ਰਹੇ ਜਲ ਸਰੋਤ",
    "Calculates 30-day moving average depletion slope (m/month) based on telemetry hydrostatic head pressure records.": "ਟੈਲੀਮੈਟਰੀ ਹਾਈਡ੍ਰੋਸਟੈਟਿਕ ਪ੍ਰੈਸ਼ਰ ਰਿਕਾਰਡਾਂ ਦੇ ਆਧਾਰ 'ਤੇ 30-ਦਿਨਾਂ ਦੀ ਔਸਤ ਗਿਰਾਵਟ ਦਰ (ਮੀਟਰ/ਮਹੀਨਾ) ਦੀ ਗਣਨਾ ਕਰਦਾ ਹੈ।",
    "Clear silt from percolation tanks and farm recharge shafts.": "ਰੀਚਾਰਜ ਛੱਪੜਾਂ ਅਤੇ ਖੇਤ ਦੇ ਰੀਚਾਰਜ ਸ਼ਾਫਟਾਂ ਵਿੱਚੋਂ ਗਾਰ ਸਾਫ਼ ਕਰੋ।",
    "Comparative state-level forecast trajectory, rainfall expectation, and agronomic priority actions": "ਤੁਲਨਾਤਮਕ ਰਾਜ-ਪੱਧਰੀ ਭਵਿੱਖਬਾਣੀ, ਬਾਰਿਸ਼ ਦੀ ਉਮੀਦ ਅਤੇ ਤਰਜੀਹੀ ਖੇਤੀਬਾੜੀ ਕਾਰਵਾਈਆਂ",
    "Concentrated in North-Western alluvial plains (Punjab, Haryana, Rajasthan) and hard-rock peninsular pockets (Kolar, Anantapur). Requires immediate crop substitution and night pumping schedules.": "ਉੱਤਰ-ਪੱਛਮੀ ਮੈਦਾਨਾਂ (ਪੰਜਾਬ, ਹਰਿਆਣਾ, ਰਾਜਸਥਾਨ) ਅਤੇ ਪਥਰੀਲੇ ਇਲਾਕਿਆਂ (ਕੋਲਾਰ, ਅਨੰਤਪੁਰ) ਵਿੱਚ ਕੇਂਦਰਿਤ। ਤੁਰੰਤ ਫਸਲੀ ਤਬਦੀਲੀ ਅਤੇ ਰਾਤ ਨੂੰ ਪੰਪਿੰਗ ਦੀ ਲੋੜ ਹੈ।",
    "Confidence": "ਵਿਸ਼ਵਾਸਯੋਗਤਾ",
    "Crop Rotation": "ਫਸਲੀ ਚੱਕਰ",
    "Crop Switch": "ਫਸਲ ਬਦਲੋ",
    "Cumulative Change": "ਕੁੱਲ ਤਬਦੀਲੀ",
    "Current Avg Depth": "ਮੌਜੂਦਾ ਔਸਤ ਡੂੰਘਾਈ",
    "Current Trend": "ਮੌਜੂਦਾ ਰੁਝਾਨ",
    "Days to critical distribution": "ਗੰਭੀਰ ਦਿਨਾਂ ਦੀ ਵੰਡ",
    "Days-to-critical estimates are calculated from current hydrostatic drawdown slope and historical monsoon infiltration response. Projections adapt dynamically as seasonal rainfall and pumping patterns change.": "ਗੰਭੀਰ ਸੀਮਾ ਤੱਕ ਦੇ ਦਿਨਾਂ ਦਾ ਅੰਦਾਜ਼ਾ ਮੌਜੂਦਾ ਪਾਣੀ ਦੇ ਡਿੱਗਣ ਦੀ ਦਰ ਅਤੇ ਪਿਛਲੇ ਮਾਨਸੂਨ ਰੀਚਾਰਜ ਤੋਂ ਲਗਾਇਆ ਜਾਂਦਾ ਹੈ। ਬਾਰਿਸ਼ ਅਤੇ ਪੰਪਿੰਗ ਅਨੁਸਾਰ ਅੰਦਾਜ਼ੇ ਬਦਲਦੇ ਹਨ।",
    "Estimated as (Current Depth - Critical Threshold) / Daily Depletion Rate, bounded by seasonal rainfall recharge coefficients.": "(ਮੌਜੂਦਾ ਡੂੰਘਾਈ - ਗੰਭੀਰ ਸੀਮਾ) / ਰੋਜ਼ਾਨਾ ਗਿਰਾਵਟ ਦਰ ਵਜੋਂ ਅੰਦਾਜ਼ਾ ਲਗਾਇਆ ਗਿਆ ਹੈ, ਜੋ ਮੌਸਮੀ ਬਾਰਿਸ਼ ਰੀਚਾਰਜ ਗੁਣਾਂਕ ਦੁਆਰਾ ਸੀਮਿਤ ਹੈ।",
    "Expected": "ਅਨੁਮਾਨਿਤ",
    "Expected Rainfall": "ਸੰਭਾਵਿਤ ਬਾਰਿਸ਼",
    "Explore Water-Smart Crops": "ਘੱਟ ਪਾਣੀ ਵਾਲੀਆਂ ਫਸਲਾਂ ਦੇਖੋ",
    "Falling": "ਡਿੱਗ ਰਿਹਾ",
    "Farming Sowing Decision": "ਬਿਜਾਈ ਦਾ ਫੈਸਲਾ",
    "Favorable soil moisture for diversified commercial rotations.": "ਵਿਭਿੰਨ ਵਪਾਰਕ ਫਸਲਾਂ ਲਈ ਅਨੁਕੂਲ ਮਿੱਟੀ ਦੀ ਨਮੀ।",
    "Field Bunding": "ਖੇਤ ਦੀ ਬੰਨ੍ਹਬੰਦੀ",
    "Forecast Insight": "ਭਵਿੱਖਬਾਣੀ ਅੰਦਰੂਨੀ ਜਾਣਕਾਰੀ",
    "Forecast Note": "ਭਵਿੱਖਬਾਣੀ ਨੋਟ",
    "Forecast Rainfall (mm)": "ਅਨੁਮਾਨਿਤ ਬਾਰਿਸ਼ (ਮਿਮੀ)",
    "Forecast Range": "ਭਵਿੱਖਬਾਣੀ ਸੀਮਾ",
    "Full Sowing Cycle": "ਪੂਰਾ ਬਿਜਾਈ ਚੱਕਰ",
    "Healthy & Recharging Aquifers": "ਸਿਹਤਮੰਦ ਅਤੇ ਰੀਚਾਰਜ ਹੋ ਰਹੇ ਜਲ ਸਰੋਤ",
    "High Risk & Stressed": "ਉੱਚ ਜੋਖਮ ਅਤੇ ਤਣਾਅਪੂਰਨ",
    "High Risk / Critical": "ਉੱਚ ਜੋਖਮ / ਗੰਭੀਰ",
    "Higher expected monsoon rainfall (62mm–95mm in Days 8–30) may support shallow aquifer recovery across central and eastern alluvial basins. However, infiltration in clay and hard-rock soils occurs with a 10–20 day lag. Farmers in deep sandstone zones should not rely on immediate water table rise.": "ਜ਼ਿਆਦਾ ਬਾਰਿਸ਼ (8-30 ਦਿਨਾਂ ਵਿੱਚ 62mm–95mm) ਮੱਧ ਅਤੇ ਪੂਰਬੀ ਮੈਦਾਨਾਂ ਵਿੱਚ ਪਾਣੀ ਦਾ ਪੱਧਰ ਸੁਧਾਰਨ ਵਿੱਚ ਮਦਦ ਕਰ ਸਕਦੀ ਹੈ। ਪਰ ਚੀਕਣੀ ਮਿੱਟੀ ਅਤੇ ਪੱਥਰੀਲੀ ਜ਼ਮੀਨ ਵਿੱਚ ਪਾਣੀ ਜਜ਼ਬ ਹੋਣ ਨੂੰ 10-20 ਦਿਨ ਲੱਗਦੇ ਹਨ। ਡੂੰਘੇ ਬੋਰਾਂ ਵਾਲੇ ਕਿਸਾਨ ਤੁਰੰਤ ਪਾਣੀ ਵਧਣ 'ਤੇ ਨਿਰਭਰ ਨਾ ਰਹਿਣ।",
    "Historical Avg": "ਇਤਿਹਾਸਕ ਔਸਤ",
