    "proactive_status_recovery": "\u0b30\u0b3f\u0b1a\u0b3e\u0b30\u0b4d\u0b1c \u0b13 \u0b2a\u0b41\u0b28\u0b30\u0b41\u0b26\u0b4d\u0b27\u0b3e\u0b30 \u0b38\u0b19\u0b4d\u0b15\u0b47\u0b24",
    "proactive_status_data_quality": "\u0b21\u0b3e\u0b1f\u0b3e \u0b17\u0b41\u0b23\u0b2c\u0b24\u0b4d\u0b24\u0b3e \u0b2f\u0b3e\u0b1e\u0b4d\u0b1a \u0b06\u0b2c\u0b36\u0b4d\u0b5f\u0b15",
    "proactive_status_stable": "\u0b2d\u0b42\u0b24\u0b33 \u0b1c\u0b33 \u0b38\u0b4d\u0b25\u0b3f\u0b24\u0b3f \u0b38\u0b4d\u0b25\u0b3f\u0b30",
    "proactive_what_changed": "\u0b15\u0b23 \u0b2a\u0b30\u0b3f\u0b2c\u0b30\u0b4d\u0b24\u0b4d\u0b24\u0b28 \u0b39\u0b4b\u0b07\u0b1b\u0b3f",
    "proactive_what_to_do": "\u0b2a\u0b30\u0b3e\u0b2e\u0b30\u0b4d\u0b36\u0b3f\u0b24 \u0b2a\u0b26\u0b15\u0b4d\u0b37\u0b47\u0b2a",
    "provenance_water_watch": "\u0b1c\u0b33\u0b15\u0b43\u0b37\u0b3f \u0b30\u0b47\u0b2b\u0b30\u0b47\u0b28\u0b4d\u0b38 \u0b38\u0b3f\u0b2e\u0b41\u0b32\u0b47\u0b38\u0b28 \u0b21\u0b3e\u0b1f\u0b3e\u0b38\u0b47\u0b1f\u0b4d",
    "ask_water_watch_voice": "\u0b15\u0b43\u0b37\u0b15 AI \u0b15\u0b41 \u0b2a\u0b1a\u0b3e\u0b30\u0b28\u0b4d\u0b24\u0b41",
