    "proactive_engine_desc": "DWLR \u0b1f\u0b4d\u0b30\u0b47\u0b23\u0b4d\u0b21 \u0b0f\u0b2c\u0b02 \u0b09\u0b2a\u0b17\u0b4d\u0b30\u0b39 \u0b38\u0b19\u0b4d\u0b15\u0b47\u0b24\u0b30 \u0b2c\u0b39\u0b41-\u0b38\u0b19\u0b4d\u0b15\u0b47\u0b24 \u0b2c\u0b3f\u0b36\u0b4d\u0b33\u0b47\u0b37\u0b23\u0964",
    "refresh_intelligence": "\u0b30\u0b3f\u0b2b\u0b4d\u0b30\u0b47\u0b36\u0b4d \u0b15\u0b30\u0b28\u0b4d\u0b24\u0b41",
    "proactive_provenance_disclaimer": "\u0b30\u0b47\u0b2b\u0b30\u0b47\u0b28\u0b4d\u0b38 \u0b38\u0b3f\u0b2e\u0b41\u0b32\u0b47\u0b38\u0b28 \u0b2e\u0b4b\u0b21\u0b4d \u0b30\u0b47 \u0b15\u0b3e\u0b30\u0b4d\u0b2f\u0b4d\u0b5f \u0b15\u0b30\u0b41\u0b1b\u0b3f\u0964",
