    "kpi_escalating_risks": "\u0b2c\u0b43\u0b26\u0b4d\u0b27\u0b3f \u0b2a\u0b3e\u0b09\u0b25\u0b3f\u0b2c\u0b3e \u0b2c\u0b3f\u0b2a\u0b26",
