    "proactive_filters_heading": "\u0b2c\u0b3f\u0b2a\u0b26 \u0b38\u0b4d\u0b24\u0b30 \u0b0f\u0b2c\u0b02 \u0b2a\u0b26\u0b15\u0b4d\u0b37\u0b47\u0b2a",
