    "no_proactive_alerts_found": "\u0b15\u0b4c\u0b23\u0b38\u0b3f \u0b38\u0b15\u0b4d\u0b30\u0b3f\u0b5f \u0b1a\u0b47\u0b24\u0b3e\u0b2c\u0b28\u0b40 \u0b2e\u0b3f\u0b33\u0b3f\u0b28\u0b3e\u0b39\u0b3f\u0b01",
    "no_proactive_alerts_desc": "\u0b38\u0b2e\u0b38\u0b4d\u0b24 \u0b28\u0b3f\u0b30\u0b40\u0b15\u0b4d\u0b37\u0b23 \u0b15\u0b47\u0b28\u0b4d\u0b26\u0b4d\u0b30 \u0b2c\u0b30\u0b4d\u0b24\u0b4d\u0b24\u0b2e\u0b3e\u0b28 \u0b38\u0b4d\u0b25\u0b3f\u0b30 \u0b30\u0b39\u0b3f\u0b1b\u0b3f\u0964",
    "Proactive Intelligence": "\u0b38\u0b15\u0b4d\u0b30\u0b3f\u0b5f \u0b2c\u0b41\u0b26\u0b4d\u0b27\u0b3f\u0b2e\u0b24\u0b4d\u0b24\u0b3e",    "Severity:": "ଗୁରୁତରତା:",
    "Category:": "ଶ୍ରେଣୀ:",
    "Detected:": "ଚିହ୍ନଟ ସମୟ:",
    "Try selecting 'All Severities' or clearing your search keywords.": "'ସମସ୍ତ ଗୁରୁତରତା' ଚୟନ କରନ୍ତୁ କିମ୍ବା ଆପଣଙ୍କ ଖୋଜ ଶବ୍ଦଗୁଡ଼ିକୁ ସଫା କରନ୍ତୁ।",
    "All States": "ସମସ୍ତ ରାଜ୍ୟ",
    "Groundwater Early Warning Engine": "ଭୂତଳ ଜଳ ପ୍ରାଥମିକ ଚେତାବନୀ ଇଞ୍ଜିନ",
    "Groundwater Change & Data Quality Monitoring": "ଭୂତଳ ଜଳ ପରିବର୍ତ୍ତନ ଏବଂ ତଥ୍ୟ ଗୁଣବତ୍ତା ନିରୀକ୍ଷଣ",
    "Reference Simulation Data": "ରେଫରେନ୍ସ ସିମ୍ୟୁଲେସନ୍ ଡାଟା",
    "Groundwater Anomaly Detection & Early Warnings": "ଭୂତଳ ଜଳ ଅସଙ୍ଗତି ଚିହ୍ନଟ ଏବଂ ପ୍ରାଥମିକ ଚେତାବନୀ",
    "Detect unusual groundwater changes, distinguish possible water-level stress from sensor-quality issues, and identify areas that may need attention.": "ଅସ୍ବାଭାବିକ ଭୂତଳ ଜଳ ପରିବର୍ତ୍ତନ ଚିହ୍ନଟ କରନ୍ତୁ, ଜଳସ୍ତର ଚାପ ଏବଂ ସେନ୍ସର ଗୁଣବତ୍ତା ସମସ୍ୟା ମଧ୍ୟରେ ପାର୍ଥକ୍ୟ ବୁଝନ୍ତୁ ଏବଂ ଧ୍ୟାନ ଦେବା ଆବଶ୍ୟକ କ୍ଷେତ୍ରଗୁଡ଼ିକୁ ଚିହ୍ନଟ କରନ୍ତୁ।",
    "An unusual groundwater change can indicate increasing water stress, abnormal extraction, or a data-quality issue. Early review can help farmers and officials respond before water availability becomes a larger problem.": "ଏକ ଅସ୍ବାଭାବିକ ଭୂତଳ ଜଳ ପରିବର୍ତ୍ତନ ବଢୁଥିବା ଜଳ ଚାପ, ଅତ୍ୟଧିକ ଜଳ ନିଷ୍କାସନ କିମ୍ବା ତଥ୍ୟ ଗୁଣବତ୍ତା ସମସ୍ୟାର ସୂଚକ ହୋଇପାରେ। ସମୟ ପୂର୍ବରୁ ସମୀକ୍ଷା କରିବା ଦ୍ୱାରା କୃଷକ ଏବଂ ଅଧିକାରୀମାନେ ପଦକ୍ଷେପ ନେଇପାରିବେ।",
    "Detected Anomaly Signals": "ଚିହ୍ନଟ ହୋଇଥିବା ଅସଙ୍ଗତି ସଙ୍କେତ",
    "Anomaly Signals": "ଅସଙ୍ଗତି ସଙ୍କେତ",
    "Signals requiring review": "ସମୀକ୍ଷା ଆବଶ୍ୟକ କରୁଥିବା ସଙ୍କେତ",
    "Reference Analysis": "ରେଫରେନ୍ସ ବିଶ୍ଳେଷଣ",
    "Critical Groundwater Drops": "ଗୁରୁତର ଭୂତଳ ଜଳ ହ୍ରାସ",
    "Immediate attention": "ତୁରନ୍ତ ଧ୍ୟାନ ଆବଶ୍ୟକ",
    "Immediate Review": "ତୁରନ୍ତ ସମୀକ୍ଷା",
    "Unusual Extraction Patterns": "ଅସ୍ବାଭାବିକ ଜଳ ନିଷ୍କାସନ ଧାରା",
    "Review water-use pattern": "ଜଳ ବ୍ୟବହାର ଧାରାର ସମୀକ୍ଷା କରନ୍ତୁ",
