    "Data Quality Issues": "ତଥ୍ୟ ଗୁଣବତ୍ତା ସମସ୍ୟା",
    "Verify observations": "ନିରୀକ୍ଷଣଗୁଡ଼ିକ ଯାଞ୍ଚ କରନ୍ତୁ",
    "Verification Required": "ଯାଞ୍ଚ ଆବଶ୍ୟକ",
    "Sudden Groundwater Drop": "ହଠାତ୍ ଭୂତଳ ଜଳ ହ୍ରାସ",
