    "Possible Abnormal Extraction": "ସମ୍ଭାବ୍ୟ ଅସ୍ବାଭାବିକ ଜଳ ନିଷ୍କାସନ",
    "Repeated drawdown may indicate unusually high or sustained water withdrawal.": "ବାରମ୍ବାର ହ୍ରାସ ଅତ୍ୟଧିକ କିମ୍ବା ନିରନ୍ତର ଜଳ ନିଷ୍କାସନକୁ ସୂଚିତ କରିପାରେ।",
