    "Possible Sensor Data Issue": "ସମ୍ଭାବ୍ୟ ସେନ୍ସର ତଥ୍ୟ ସମସ୍ୟା",
    "Readings show patterns that may require sensor or telemetry verification.": "ରିଡିଂ ଏପରି ଧାରା ଦର୍ଶାଉଛି ଯାହା ସେନ୍ସର କିମ୍ବା ଟେଲିମେଟ୍ରି ଯାଞ୍ଚ ଆବଶ୍ୟକ କରିପାରେ।",
    "Sudden Groundwater Rise": "ହଠାତ୍ ଭୂତଳ ଜଳ ବୃଦ୍ଧି",
