    "30-day precipitation projections (mm) vs normal baseline and calculated infiltration recharge potential": "ସାଧାରଣ ସ୍ତର ତୁଳନାରେ ୩୦-ଦିନର ବର୍ଷା ପୂର୍ବାନୁମାନ (ମିମି) ଏବଂ ଭୂତଳ ଜଳ ପୁନର୍ଭରଣ କ୍ଷମତା",
    "30d Projected": "୩୦ ଦିନର ଅନୁମାନ",
