    "Falling": "ହ୍ରାସ ପାଉଛି",
    "Farming Sowing Decision": "ବୁଣିବା ନିଷ୍ପତ୍ତି",
    "Favorable soil moisture for diversified commercial rotations.": "ବ୍ୟାବସାୟିକ ଫସଲ ପାଇଁ ଅନୁକୂଳ ମାଟିର ଆର୍ଦ୍ରତା।",
    "Field Bunding": "ଜମିର ହିଡ଼ ବାନ୍ଧିବା",
    "Forecast Insight": "ପୂର୍ବାନୁମାନ ଅନ୍ତର୍ଦୃଷ୍ଟି",
    "Forecast Note": "ପୂର୍ବାନୁମାନ ଟିପ୍ପଣୀ",
