    "Full Sowing Cycle": "ସମ୍ପୂର୍ଣ୍ଣ ବୁଣିବା ଚକ୍ର",
    "Healthy & Recharging Aquifers": "ସୁସ୍ଥ ଏବଂ ପୁନର୍ଭରଣ ହେଉଥିବା ଜଳଭଣ୍ଡାର",
    "High Risk & Stressed": "ଉଚ୍ଚ ବିପଦ ଏବଂ ଚାପଗ୍ରସ୍ତ",
    "High Risk / Critical": "ଉଚ୍ଚ ବିପଦ / ଗୁରୁତର",
    "Higher expected monsoon rainfall (62mm–95mm in Days 8–30) may support shallow aquifer recovery across central and eastern alluvial basins. However, infiltration in clay and hard-rock soils occurs with a 10–20 day lag. Farmers in deep sandstone zones should not rely on immediate water table rise.": "ଅଧିକ ମୌସୁମୀ ବର୍ଷା (୮-୩୦ ଦିନ ମଧ୍ୟରେ ୬୨ମିମି–୯୫ମିମି) ମଧ୍ୟ ଓ ପୂର୍ବ ସମତଳ ଅଞ୍ଚଳରେ ଜଳସ୍ତର ସୁଧାରିବାରେ ସାହାଯ୍ୟ କରିପାରେ। କିନ୍ତୁ କାଦୁଅ ଏବଂ ପଥୁରିଆ ମାଟିରେ ଜଳ ଶୋଷଣ ପାଇଁ ୧୦-୨୦ ଦିନ ଲାଗେ। ଗଭୀର ନଳକୂପ ଥିବା ଚାଷୀମାନେ ତୁରନ୍ତ ଜଳ ବୃଦ୍ଧି ଉପରେ ନିର୍ଭର କରିବା ଉଚିତ ନୁହେଁ।",
    "Historical Avg": "ପୂର୍ବ ହାରାହାରି",
    "Historical Normal (mm)": "ପୂର୍ବ ସାଧାରଣ (ମିମି)",
    "Imminent": "ଖୁବ୍ ନିକଟରେ",
    "Implement drip lines to achieve 40% water savings.": "୪୦% ଜଳ ସଞ୍ଚୟ ପାଇଁ ବୁନ୍ଦା ସେଚନ ବ୍ୟବହାର କରନ୍ତୁ।",
