    "Groundwater level is falling faster than the expected local pattern. This may indicate concentrated pumping or rapid localized depletion.": "ভূগৰ্ভস্থ জলস্তৰ প্ৰত্যাশিত হাৰতকৈ দ্ৰুতগতিত হ্ৰাস পাইছে। ই অত্যধিক পাম্পিং বা দ্ৰুত স্থানীয় হ্ৰাসৰ ইংগিত দিব পাৰে।",
