    "Expected observations are missing or arriving later than expected. Commonly caused by temporary network interruptions or power cycling.": "প্ৰত্যাশিত পৰ্যবেক্ষণসমূহ পোৱা হোৱা নাই বা পলমকৈ আহিছে। সাধাৰণতে অস্থায়ী নেটৱৰ্ক বা পাৱাৰ সমস্যাৰ বাবে এনে হয়।",
    "Unusual reading patterns requiring check": "অস্বাভাৱিক ৰিডিং নমুনা, পৰীক্ষাৰ প্ৰয়োজন",
    "Readings show patterns that may require sensor or telemetry verification before drawing firm hydrogeological conclusions.": "চূড়ান্ত সিদ্ধান্ত লোৱাৰ পূৰ্বে চেন্সৰ বা টেলিমেট্ৰি নিশ্চিতকৰণৰ প্ৰয়োজন হ'ব পাৰে।",
    "Rapid water level increase": "জলস্তৰত দ্ৰুত বৃদ্ধি",
    "Groundwater level has increased sharply, potentially following heavy localized rainfall, canal release, or surface recharge.": "প্ৰচুৰ বৰষুণ, খালৰ পানী বা পুনৰ্ভৰণৰ ফলত ভূগৰ্ভস্থ জলস্তৰ দ্ৰুতগতিত বৃদ্ধি পাইছে।",
    "Recommended Next Steps": "পৰামৰ্শিত পৰৱৰ্তী পদক্ষেপ",
    "Actionable guidance for farmers and field officials when unusual signals are detected": "অস্বাভাবিক সংকেত পোৱা গ'লে কৃষক আৰু বিষয়া সকলৰ বাবে ব্যৱহাৰিক নিৰ্দেশনা",
    "Water Drop": "জলস্তৰ পতন",
    "Check Groundwater Forecast": "ভূগৰ্ভস্থ জলৰ পূৰ্বাভাস চাওক",
    "Review projected days-to-critical and consider adjusting pumping intervals or pump depth.": "সংকটপূৰ্ণ দিনৰ পূৰ্বানুমান পুনৰীক্ষণ কৰক আৰু পাম্পিং সময়ৰ ব্যৱধান ঠিক কৰাৰ কথা চিন্তা কৰক।",
    "Inspect Neighboring Stations": "ওচৰৰ ষ্টেচনসমূহ পৰীক্ষা কৰক",
    "Explore nearby monitoring stations on the map to determine whether the drop is localized or spread across the block.": "পতন স্থানীয় নে সমগ্ৰ ব্লকত বিয়পি পৰিছে সেয়া জানিবলৈ মানচিত্ৰত ওচৰৰ ষ্টেচনসমূহ চাওক।",
    "Data Quality": "তথ্যৰ গুণগত মান",
    "Verify Latest Observations": "শেহতীয়া পৰ্যবেক্ষণসমূহ নিশ্চিত কৰক",
    "Check station telemetry status and wait for verification before planning critical irrigation changes.": "জলসিঞ্চনৰ গুৰুত্বপূৰ্ণ পৰিৱৰ্তনৰ পূৰ্বে ষ্টেচনৰ টেলিমেট্ৰি স্থিতি পৰীক্ষা কৰক।",
    "Check Station Status": "ষ্টেচনৰ স্থিতি পৰীক্ষা কৰক",
    "Recharge Surge": "পুনৰ্ভৰণ বৃদ্ধি",
