    "Active in Middle Gangetic Basin (UP, Bihar, West Bengal) and Narmada Valley (MP). Shallow aquifers exhibit +0.3m to +0.5m post-monsoon water table recovery.": "মধ্য গাংগেয় অৱবাহিকা (ইউপি, বিহাৰ, পশ্চিমবংগ) আৰু নৰ্মদা উপত্যকাত (এমপি) সক্ৰিয়। অগভীৰ জলস্তৰে বাৰিষাৰ পিছত +০.৩ মিটাৰৰ পৰা +০.৫ মিটাৰ পানীৰ স্তৰ বৃদ্ধি প্ৰদৰ্শন কৰে।",
    "Adopt mixed cropping (Maize + Pulses) to balance root-zone moisture draw.": "শিপাৰ অংশত আৰ্দ্ৰতাৰ ভাৰসাম্য ৰক্ষা কৰিবলৈ মিশ্ৰিত শস্য (মাকৈ + দাইল) খেতি কৰক।",
    "All values displayed are simulated DWLR data intended for model evaluation and operational planning. Future phases will integrate live CGWB REST telemetry endpoints and IMD meteorological grids.": "প্ৰদৰ্শিত সকলো মান মডেল মূল্যায়ন আৰু পৰিকল্পনাৰ বাবে সিমুলেটেড DWLR তথ্য। ভৱিষ্যতে লাইভ CGWB REST টেলিমেট্ৰী আৰু IMD বতৰ গ্ৰিড সংযুক্ত কৰা হ'ব।",
    "Aquifer Rebound": "জলস্তৰৰ পুনৰুদ্ধাৰ",
    "Aquifers Depleting < 30 Days": "৩০ দিনতকৈ কম সময়ত শুকাই যোৱা জলস্তৰ",
    "Calculates 30-day moving average depletion slope (m/month) based on telemetry hydrostatic head pressure records.": "টেলিমেট্ৰী হাইড্ৰ'ষ্টেটিক হেড প্ৰেচাৰ ৰেকৰ্ডৰ ভিত্তিত ৩০ দিনৰ গড় হ্ৰাসৰ ঢাল (মি/মাহ) গণনা কৰে।",
    "Clear silt from percolation tanks and farm recharge shafts.": "পানী শোধন টেংকী আৰু পথাৰৰ ৰিচাৰ্জ খাদৰ পৰা বোকা পৰিষ্কাৰ কৰক।",
    "Comparative state-level forecast trajectory, rainfall expectation, and agronomic priority actions": "তুলনামূলক ৰাজ্যিক পৰ্যায়ৰ পূৰ্বানুমান, বৰষুণৰ সম্ভাৱনা আৰু অগ্ৰাধিকাৰমূলক কৃষি পদক্ষেপ",
    "Concentrated in North-Western alluvial plains (Punjab, Haryana, Rajasthan) and hard-rock peninsular pockets (Kolar, Anantapur). Requires immediate crop substitution and night pumping schedules.": "উত্তৰ-পশ্চিম সমভূমি (পঞ্জাৱ, হাৰিয়ানা, ৰাজস্থান) আৰু উপদ্বীপীয় কঠিন শিলৰ অঞ্চলত (কোলাৰ, অনন্তপুৰ) কেন্দ্ৰীভূত। তাৎক্ষণিক শস্য পৰিৱৰ্তন আৰু ৰাতি পাম্পিং সময়সূচী প্ৰয়োজন।",
