    "Days-to-critical estimates are calculated from current hydrostatic drawdown slope and historical monsoon infiltration response. Projections adapt dynamically as seasonal rainfall and pumping patterns change.": "সংকটজনক দিনৰ অনুমান বৰ্তমানৰ পানী হ্ৰাসৰ হাৰ আৰু ঐতিহাসিক বাৰিষাৰ পুনৰ্ভৰণৰ ওপৰত ভিত্তি কৰি গণনা কৰা হয়। বৰষুণ আৰু পাম্পিং সলনি হ'লে পূৰ্বানুমান সলনি হয়।",
    "Estimated as (Current Depth - Critical Threshold) / Daily Depletion Rate, bounded by seasonal rainfall recharge coefficients.": "(বৰ্তমান গভীৰতা - সংকটজনক সীমা) / দৈনিক হ্ৰাসৰ হাৰ হিচাপে আনুমানিক, যিটো বৰষুণৰ পুনৰ্ভৰণ কাৰকৰ দ্বাৰা আৱদ্ধ।",
