    "Readings show patterns that may require sensor or telemetry verification.": "ریڈنگز ایسے پیٹرن دکھاتی ہیں جن کی سینسر یا ٹیلی میٹری تصدیق کی ضرورت ہو سکتی ہے۔",
    "Sudden Groundwater Rise": "زیر زمین پانی میں اچانک اضافہ",
    "Groundwater level has increased sharply, potentially following rainfall or recharge conditions.": "بارش یا ریچارج کی صورتحال کے بعد زیر زمین پانی کی سطح میں تیزی سے اضافہ ہوا ہے۔",
    "Recent Groundwater & Data Quality Signals": "حالیہ زیر زمین پانی اور ڈیٹا کوالٹی سگنلز",
    "Critical (Immediate Attention)": "انتہائی اہم (فوری توجہ)",
    "High (Review Soon)": "زیادہ (جلد جائزہ لیں)",
    "Moderate (Monitor)": "معتدل (نگرانی کریں)",
    "Data Quality / Low (Verify)": "ڈیٹا کوالٹی / کم (تصدیق کریں)",
    "Why Flagged / Insight:": "انتباہ کی وجہ / تجزیہ:",
    "Plain-Language Assessment": "آسان زبان میں جائزہ",
    "Recommended Follow-up Action": "تجویز کردہ آئندہ کارروائی",
    "Technical Evidence & Telemetry Details": "تکنیکی شواہد اور ٹیلی میٹری کی تفصیلات",
    "Observation Timeline vs Expected Baseline": "مشاہداتی ٹائم لائن بمقابلہ متوقع بیس لائن",
    "Sensor / Hardware Status:": "سینسر / ہارڈویئر کی حیثیت:",
    "Observation Status": "مشاہداتی حیثیت",
    "Early Warning Signal": "قبل از وقت وارننگ سگنل",
    "Understanding Groundwater Anomalies": "زیر زمین پانی کی غیر معمولی تبدیلیوں کو سمجھنا",
    "Plain-language guide to groundwater early warning flags and data quality signals": "زیر زمین پانی کی قبل از وقت وارننگ اور ڈیٹا کوالٹی سگنلز کی آسان گائیڈ",
    "Water level falling faster than expected": "پانی کی سطح توقع سے زیادہ تیزی سے گر رہی ہے",
    "Groundwater level is falling faster than the expected local pattern. This may indicate concentrated pumping or rapid localized depletion.": "زیر زمین پانی کی سطح معمول سے زیادہ تیزی سے گر رہی ہے۔ یہ ضرورت سے زیادہ پمپنگ یا تیز رفتار مقامی کمی کی علامت ہو سکتی ہے۔",
    "Repeated drawdown without normal recovery": "معمول کی بحالی کے بغیر مسلسل کمی",
    "Repeated drawdown may indicate unusually high or sustained water withdrawal without the usual recharge window.": "ریچارج کے بغیر مسلسل کمی غیر معمولی یا مسلسل پانی نکالنے کی علامت ہو سکتی ہے۔",
    "Expected readings not received": "متوقع ریڈنگز موصول نہیں ہوئیں",
    "Expected observations are missing or arriving later than expected. Commonly caused by temporary network interruptions or power cycling.": "متوقع مشاہدات غائب ہیں یا تاخیر سے آ رہے ہیں۔ یہ عام طور پر عارضی نیٹ ورک یا بجلی کے مسائل کی وجہ سے ہوتا ہے۔",
    "Unusual reading patterns requiring check": "غیر معمولی ریڈنگ پیٹرن، جانچ درکار ہے",
    "Readings show patterns that may require sensor or telemetry verification before drawing firm hydrogeological conclusions.": "حتمی نتائج اخذ کرنے سے پہلے سینسر یا ٹیلی میٹری تصدیق کی ضرورت ہو سکتی ہے۔",
    "Rapid water level increase": "پانی کی سطح میں تیز رفتار اضافہ",
    "Groundwater level has increased sharply, potentially following heavy localized rainfall, canal release, or surface recharge.": "شدید مقامی بارش، نہری پانی یا ریچارج کے نتیجے میں زیر زمین پانی کی سطح میں تیزی سے اضافہ ہوا ہے۔",
    "Recommended Next Steps": "تجویز کردہ اگلے اقدامات",
    "Actionable guidance for farmers and field officials when unusual signals are detected": "غیر معمولی سگنلز ملنے پر کسانوں اور فیلڈ افسران کے لیے قابل عمل رہنمائی",
    "Water Drop": "پانی کی سطح میں کمی",
    "Check Groundwater Forecast": "زیر زمین پانی کی پیشن گوئی دیکھیں",
    "Review projected days-to-critical and consider adjusting pumping intervals or pump depth.": "اہم ترین دنوں کا جائزہ لیں اور پمپنگ کے وقفوں یا پمپ کی گہرائی کو ایڈجسٹ کرنے پر غور کریں۔",
    "Inspect Neighboring Stations": "قریبی اسٹیشنوں کا معائنہ کریں",
    "Explore nearby monitoring stations on the map to determine whether the drop is localized or spread across the block.": "نقشے پر قریبی مانیٹرنگ اسٹیشنز دیکھیں تاکہ معلوم ہو سکے کہ کمی مقامی ہے یا پورے بلاک میں پھیلی ہوئی ہے۔",
    "Data Quality": "ڈیٹا کوالٹی",
    "Verify Latest Observations": "تازہ ترین مشاہدات کی تصدیق کریں",
    "Check station telemetry status and wait for verification before planning critical irrigation changes.": "آبپاشی میں اہم تبدیلیوں کی منصوبہ بندی کرنے سے پہلے اسٹیشن کی ٹیلی میٹری کی حیثیت چیک کریں۔",
    "Check Station Status": "اسٹیشن کی حیثیت چیک کریں",
    "Recharge Surge": "ریچارج میں اضافہ",
    "Optimize Crop Planning": "فصلوں کی منصوبہ بندی کو بہتر بنائیں",
    "Assess soil moisture and explore suitable crop rotation options to take advantage of improved water availability.": "مٹی کی نمی کا اندازہ لگائیں اور پانی کی بہتر دستیابی سے فائدہ اٹھانے کے لیے مناسب فصلوں کے تناسب کے اختیارات تلاش کریں۔",
    "Where are Signals Concentrated? (Regional Breakdown)": "سگنلز کہاں مرکوز ہیں؟ (علاقائی تفصیل)",
    "Ranked states by detected signals and primary anomaly category": "شناخت شدہ سگنلز اور بنیادی غیر معمولی زمرے کے لحاظ سے ریاستوں کی درجہ بندی",
